CREATE OR REPLACE FUNCTION public._apply_table_rls(p_table text, view_perm text, insert_perm text, update_perm text, delete_perm text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_schema text;
  v_table text;
  v_regclass regclass;
BEGIN
  IF position('.' IN p_table) > 0 THEN
    v_schema := split_part(p_table, '.', 1);
    v_table := split_part(p_table, '.', 2);
  ELSE
    v_schema := 'public';
    v_table := p_table;
  END IF;

  IF NOT EXISTS (
    SELECT 1
    FROM information_schema.tables
    WHERE table_schema = v_schema
      AND table_name = v_table
  ) THEN
    RAISE NOTICE 'Skipping RLS: table %.% does not exist', v_schema, v_table;
    RETURN;
  END IF;

  v_regclass := (format('%I.%I', v_schema, v_table))::regclass;

  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', v_regclass);

  EXECUTE format('DROP POLICY IF EXISTS %I ON %s', v_table || '_select', v_regclass);
  EXECUTE format(
    'CREATE POLICY %I ON %s FOR SELECT TO authenticated USING (public.require_permission(%L))',
    v_table || '_select',
    v_regclass,
    view_perm
  );

  EXECUTE format('DROP POLICY IF EXISTS %I ON %s', v_table || '_insert', v_regclass);
  EXECUTE format(
    'CREATE POLICY %I ON %s FOR INSERT TO authenticated WITH CHECK (public.require_permission(%L))',
    v_table || '_insert',
    v_regclass,
    insert_perm
  );

  EXECUTE format('DROP POLICY IF EXISTS %I ON %s', v_table || '_update', v_regclass);
  EXECUTE format(
    'CREATE POLICY %I ON %s FOR UPDATE TO authenticated USING (public.require_permission(%L)) WITH CHECK (public.require_permission(%L))',
    v_table || '_update',
    v_regclass,
    update_perm,
    update_perm
  );

  EXECUTE format('DROP POLICY IF EXISTS %I ON %s', v_table || '_delete', v_regclass);
  EXECUTE format(
    'CREATE POLICY %I ON %s FOR DELETE TO authenticated USING (public.require_permission(%L))',
    v_table || '_delete',
    v_regclass,
    delete_perm
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public._apply_table_rls(target_table regclass, read_perm text DEFAULT NULL::text, write_perm text DEFAULT NULL::text, manage_perm text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    table_name_str text;
BEGIN
    table_name_str := target_table::text;

    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY;', table_name_str);

    EXECUTE format('DROP POLICY IF EXISTS "select_policy_%s" ON %s;', replace(table_name_str, '.', '_'), table_name_str);
    EXECUTE format('DROP POLICY IF EXISTS "manage_policy_%s" ON %s;', replace(table_name_str, '.', '_'), table_name_str);

    EXECUTE format('
        CREATE POLICY "select_policy_%s" ON %s
        FOR SELECT TO authenticated
        USING (
            public.is_admin() OR 
            (%L IS NOT NULL AND public.has_permission(%L))
        );', 
        replace(table_name_str, '.', '_'), table_name_str, read_perm, read_perm
    );

    EXECUTE format('
        CREATE POLICY "manage_policy_%s" ON %s
        FOR ALL TO authenticated
        USING (
            public.is_admin() OR 
            (%L IS NOT NULL AND public.has_permission(%L))
        );', 
        replace(table_name_str, '.', '_'), table_name_str, manage_perm, manage_perm
    );
EXCEPTION WHEN OTHERS THEN
    -- در صورت نبود جدول یا اشتباه در آرگومان، از آن عبور می‌کند تا میگریشن متوقف نشود
    RAISE NOTICE 'Skipping RLS for table %, Error: %', target_table, SQLERRM;
END;
$function$;

CREATE OR REPLACE FUNCTION public._fifo_consume_for_document(p_product_id uuid, p_quantity numeric, p_source_type text, p_source_id uuid, p_fallback_cost numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_remaining NUMERIC := COALESCE(p_quantity, 0);
  v_batch     RECORD;
  v_take      NUMERIC;
  v_cost      NUMERIC := 0;
BEGIN
  IF v_remaining <= 0 THEN
    RETURN 0;
  END IF;

  FOR v_batch IN
    SELECT id, remaining_qty, unit_cost
    FROM public.inventory_batches
    WHERE product_id = p_product_id AND remaining_qty > 0
    ORDER BY created_at ASC, id ASC
    FOR UPDATE
  LOOP
    EXIT WHEN v_remaining <= 0.0001;
    v_take := LEAST(v_remaining, v_batch.remaining_qty);

    UPDATE public.inventory_batches SET remaining_qty = remaining_qty - v_take WHERE id = v_batch.id;

    INSERT INTO public.inventory_batch_consumptions (
      batch_id, product_id, quantity, unit_cost, cogs_amount, source_type, source_id
    ) VALUES (
      v_batch.id, p_product_id, v_take, v_batch.unit_cost,
      ROUND(v_take * v_batch.unit_cost, 2), p_source_type, p_source_id
    );

    v_cost := v_cost + ROUND(v_take * v_batch.unit_cost, 2);
    v_remaining := v_remaining - v_take;
  END LOOP;

  IF v_remaining > 0.0001 THEN
    v_cost := v_cost + ROUND(v_remaining * GREATEST(COALESCE(p_fallback_cost, 0), 0), 2);
  END IF;

  RETURN ROUND(v_cost, 2);
END;
$function$;

CREATE OR REPLACE FUNCTION public.apply_document_additional_expenses(p_expenses jsonb, p_source_type text, p_source_id uuid, p_doc_ref text)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_exp JSONB;
  v_amount NUMERIC;
  v_total NUMERIC := 0;
  v_account_id UUID;
  v_label TEXT;
  v_paid BOOLEAN;
BEGIN
  IF p_expenses IS NULL OR jsonb_typeof(p_expenses) <> 'array' THEN
    RETURN 0;
  END IF;

  FOR v_exp IN SELECT value FROM jsonb_array_elements(p_expenses)
  LOOP
    v_amount := COALESCE(NULLIF(v_exp->>'amount', '')::numeric, 0);
    IF v_amount <= 0 THEN
      CONTINUE;
    END IF;
    v_total := v_total + v_amount;
    v_paid := COALESCE((v_exp->>'paid_immediately')::boolean, false);
    IF NOT v_paid THEN
      CONTINUE;
    END IF;

    v_account_id := NULLIF(v_exp->>'account_id', '')::uuid;
    IF v_account_id IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'Ödənilən əlavə xərc üçün kassa/bank hesabı seçilməlidir';
    END IF;

    v_label := COALESCE(NULLIF(trim(v_exp->>'label'), ''), 'Əlavə xərc');

    PERFORM public.post_cash_transaction(
      v_account_id,
      'Məxaric',
      v_amount,
      'Əlavə Xərc',
      format('%s — %s', p_doc_ref, v_label),
      NULL,
      p_source_type,
      p_source_id
    );
  END LOOP;

  RETURN v_total;
END;
$function$;

CREATE OR REPLACE FUNCTION public.apply_sale_stock_decrement(p_stock_demand jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_key TEXT;
  v_product_id UUID;
  v_qty NUMERIC;
BEGIN
  IF p_stock_demand IS NULL OR jsonb_typeof(p_stock_demand) <> 'object' THEN
    RETURN;
  END IF;

  FOR v_key IN SELECT jsonb_object_keys(p_stock_demand)
  LOOP
    v_product_id := v_key::uuid;
    v_qty := COALESCE((p_stock_demand->>v_key)::numeric, 0);

    UPDATE public.products
    SET stock = COALESCE(stock, 0) - v_qty
    WHERE id = v_product_id;
  END LOOP;
END;
$function$;

