CREATE OR REPLACE FUNCTION public.assert_journal_entry_balanced()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_entry_id UUID;
  v_debit NUMERIC;
  v_credit NUMERIC;
  v_line_count INT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_entry_id := OLD.journal_entry_id;
  ELSE
    v_entry_id := NEW.journal_entry_id;
  END IF;

  SELECT
    COALESCE(SUM(debit), 0),
    COALESCE(SUM(credit), 0),
    COUNT(*)
  INTO v_debit, v_credit, v_line_count
  FROM public.journal_entry_lines
  WHERE journal_entry_id = v_entry_id;

  IF v_line_count = 0 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF abs(v_debit - v_credit) > 0.0001 THEN
    RAISE EXCEPTION 'journal_unbalanced'
      USING ERRCODE = '22023',
            MESSAGE = format(
              'Müxabirləşmə balanssızdir: debet=%s, kredit=%s (entry_id=%s)',
              v_debit,
              v_credit,
              v_entry_id
            );
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_attach_trigger(p_table text, p_name text, p_events text, p_module text, p_when text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF to_regclass(format('public.%I', p_table)) IS NULL THEN
    RAISE NOTICE 'audit_logs: skip missing table %', p_table;
    RETURN;
  END IF;

  EXECUTE format('DROP TRIGGER IF EXISTS %I ON public.%I', p_name, p_table);

  IF p_when IS NULL OR btrim(p_when) = '' THEN
    EXECUTE format(
      'CREATE TRIGGER %I AFTER %s ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_log_row_change(%L)',
      p_name,
      p_events,
      p_table,
      p_module
    );
  ELSE
    EXECUTE format(
      'CREATE TRIGGER %I AFTER %s ON public.%I FOR EACH ROW WHEN (%s) EXECUTE FUNCTION public.audit_log_row_change(%L)',
      p_name,
      p_events,
      p_table,
      p_when,
      p_module
    );
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_json_changed_keys(p_old jsonb, p_new jsonb)
 RETURNS jsonb[]
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old jsonb := COALESCE(p_old, '{}'::jsonb);
  v_new jsonb := COALESCE(p_new, '{}'::jsonb);
  v_old_diff jsonb := '{}'::jsonb;
  v_new_diff jsonb := '{}'::jsonb;
  k text;
BEGIN
  FOR k IN
    SELECT DISTINCT key
    FROM (
      SELECT jsonb_object_keys(v_old) AS key
      UNION
      SELECT jsonb_object_keys(v_new) AS key
    ) keys
  LOOP
    IF k IN ('updated_at') THEN
      CONTINUE;
    END IF;
    IF (v_old -> k) IS DISTINCT FROM (v_new -> k) THEN
      v_old_diff := v_old_diff || jsonb_build_object(k, v_old -> k);
      v_new_diff := v_new_diff || jsonb_build_object(k, v_new -> k);
    END IF;
  END LOOP;
  RETURN ARRAY[v_old_diff, v_new_diff];
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_log_read_event(p_module text, p_table text DEFAULT NULL::text, p_meta jsonb DEFAULT NULL::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cfg JSONB;
  v_track BOOLEAN;
  v_module TEXT;
  v_id UUID;
BEGIN
  IF NOT public.is_active_user() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;

  SELECT value INTO v_cfg
    FROM public.system_settings
   WHERE key = 'audit_config';

  v_track := COALESCE((v_cfg ->> 'track_read_events')::boolean, false);
  IF NOT v_track THEN
    RETURN NULL;
  END IF;

  v_module := upper(COALESCE(NULLIF(p_module, ''), 'FINANCE'));
  IF v_module NOT IN ('FINANCE', 'PRODUCTION', 'INVENTORY', 'PAYROLL', 'SECURITY') THEN
    v_module := 'FINANCE';
  END IF;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    module,
    table_name,
    record_id,
    old_values_json,
    new_values_json,
    ip_address
  )
  VALUES (
    public.audit_request_user_id(),
    'READ',
    v_module,
    NULLIF(btrim(COALESCE(p_table, '')), ''),
    NULL,
    NULL,
    COALESCE(p_meta, '{}'::jsonb),
    public.audit_request_ip()
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_log_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_module text;
  v_action text;
  v_old jsonb;
  v_new jsonb;
  v_diff jsonb[];
  v_record_id uuid;
  v_payload jsonb;
  v_log_id uuid;
  v_cfg jsonb;
  v_alert boolean;
  v_email text;
BEGIN
  IF TG_TABLE_NAME = 'audit_logs' OR TG_TABLE_NAME = 'audit_alerts' THEN
    IF TG_OP = 'DELETE' THEN
      RETURN OLD;
    END IF;
    RETURN NEW;
  END IF;

  v_module := upper(COALESCE(NULLIF(TG_ARGV[0], ''), 'FINANCE'));
  IF v_module NOT IN ('FINANCE', 'PRODUCTION', 'INVENTORY', 'PAYROLL', 'SECURITY') THEN
    v_module := 'FINANCE';
  END IF;

  IF TG_OP = 'INSERT' THEN
    v_action := 'CREATE';
    v_payload := to_jsonb(NEW);
    v_new := public.audit_sanitize_row(v_payload);
    v_old := NULL;
  ELSIF TG_OP = 'UPDATE' THEN
    v_action := 'UPDATE';
    v_payload := to_jsonb(NEW);
    v_old := public.audit_sanitize_row(to_jsonb(OLD));
    v_new := public.audit_sanitize_row(v_payload);
    v_diff := public.audit_json_changed_keys(v_old, v_new);
    IF v_diff[1] = '{}'::jsonb AND v_diff[2] = '{}'::jsonb THEN
      RETURN NEW;
    END IF;
    v_old := v_diff[1];
    v_new := v_diff[2];
  ELSE
    v_action := 'DELETE';
    v_payload := to_jsonb(OLD);
    v_old := public.audit_sanitize_row(v_payload);
    v_new := NULL;
  END IF;

  BEGIN
    IF v_payload ? 'id' AND nullif(v_payload->>'id', '') IS NOT NULL THEN
      v_record_id := (v_payload->>'id')::uuid;
    ELSIF v_payload ? 'product_id' AND nullif(v_payload->>'product_id', '') IS NOT NULL THEN
      v_record_id := (v_payload->>'product_id')::uuid;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    v_record_id := NULL;
  END;

  INSERT INTO public.audit_logs (
    user_id,
    action,
    module,
    table_name,
    record_id,
    old_values_json,
    new_values_json,
    ip_address
  ) VALUES (
    public.audit_request_user_id(),
    v_action,
    v_module,
    TG_TABLE_NAME,
    v_record_id,
    v_old,
    v_new,
    public.audit_request_ip()
  )
  RETURNING id INTO v_log_id;

  IF v_action = 'DELETE' THEN
    SELECT value INTO v_cfg
      FROM public.system_settings
     WHERE key = 'audit_config';
    v_alert := COALESCE((v_cfg ->> 'alert_on_record_deletion')::boolean, true);

    IF v_alert AND v_module IN ('FINANCE', 'INVENTORY') THEN
      SELECT email INTO v_email FROM public.company_settings LIMIT 1;

      INSERT INTO public.audit_alerts (
        audit_log_id,
        module,
        table_name,
        record_id,
        user_id,
        message,
        email_to,
        email_status
      )
      VALUES (
        v_log_id,
        v_module,
        TG_TABLE_NAME,
        v_record_id,
        public.audit_request_user_id(),
        format(
          'High-risk DELETE: %s.%s (%s)',
          v_module,
          TG_TABLE_NAME,
          COALESCE(v_record_id::text, 'no-id')
        ),
        NULLIF(btrim(COALESCE(v_email, '')), ''),
        CASE
          WHEN NULLIF(btrim(COALESCE(v_email, '')), '') IS NULL THEN 'skipped'
          ELSE 'logged'
        END
      );
    END IF;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_request_ip()
 RETURNS inet
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_headers jsonb;
  v_xff text;
  v_ip inet;
BEGIN
  BEGIN
    v_headers := current_setting('request.headers', true)::jsonb;
  EXCEPTION WHEN OTHERS THEN
    v_headers := NULL;
  END;

  IF v_headers IS NOT NULL THEN
    v_xff := COALESCE(
      v_headers ->> 'x-forwarded-for',
      v_headers ->> 'x-real-ip',
      v_headers ->> 'cf-connecting-ip'
    );
    IF v_xff IS NOT NULL AND btrim(v_xff) <> '' THEN
      BEGIN
        v_ip := split_part(btrim(v_xff), ',', 1)::inet;
        RETURN v_ip;
      EXCEPTION WHEN OTHERS THEN
        v_ip := NULL;
      END;
    END IF;
  END IF;

  RETURN inet_client_addr();
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_request_user_id()
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid uuid;
  v_sub text;
BEGIN
  BEGIN
    v_uid := auth.uid();
  EXCEPTION WHEN OTHERS THEN
    v_uid := NULL;
  END;
  IF v_uid IS NOT NULL THEN
    RETURN v_uid;
  END IF;

  BEGIN
    v_sub := nullif(current_setting('request.jwt.claim.sub', true), '');
    IF v_sub IS NOT NULL THEN
      RETURN v_sub::uuid;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL;
  END;

  RETURN NULL;
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_sanitize_row(p_row jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_row IS NULL THEN
    RETURN NULL;
  END IF;
  RETURN p_row
    - 'password'
    - 'hashed_password'
    - 'encrypted_password'
    - 'token'
    - 'access_token'
    - 'refresh_token'
    - 'secret'
    - 'api_key'
    - 'service_role_key';
END;
$function$;

CREATE OR REPLACE FUNCTION public.audit_when_columns_changed(p_table text, p_columns text[])
 RETURNS text
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_col text;
  v_parts text := '';
BEGIN
  FOREACH v_col IN ARRAY p_columns LOOP
    IF EXISTS (
      SELECT 1
      FROM information_schema.columns
      WHERE table_schema = 'public'
        AND table_name = p_table
        AND column_name = v_col
    ) THEN
      IF v_parts <> '' THEN
        v_parts := v_parts || ' OR ';
      END IF;
      v_parts := v_parts || format('OLD.%I IS DISTINCT FROM NEW.%I', v_col, v_col);
    END IF;
  END LOOP;
  RETURN NULLIF(v_parts, '');
END;
$function$;

CREATE OR REPLACE FUNCTION public.az_payroll_statutory(p_gross numeric, p_year integer DEFAULT 2026)
 RETURNS TABLE(dsmf_employee numeric, dsmf_employer numeric, its_employee numeric, its_employer numeric, income_tax numeric, taxable_income numeric)
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_gross NUMERIC := GREATEST(COALESCE(p_gross, 0), 0);
  v_cfg JSONB;
  v_ee_rate NUMERIC;
  v_er_rate NUMERIC;
  v_its_rate NUMERIC;
  v_limit NUMERIC;
  v_first NUMERIC;
  v_mid NUMERIC;
  v_above NUMERIC;
  v_dsmf_ee NUMERIC;
  v_dsmf_er NUMERIC;
  v_its NUMERIC;
  v_taxable NUMERIC;
  v_pit_base NUMERIC;
  v_low_rate NUMERIC;
  v_low_tax NUMERIC;
  v_mid_tax NUMERIC;
  v_pit NUMERIC;
BEGIN
  SELECT value INTO v_cfg
    FROM public.system_settings
   WHERE key = 'tax_payroll_config';

  v_ee_rate := GREATEST(COALESCE((v_cfg ->> 'dsmf_employee_rate')::numeric, 3), 0) / 100.0;
  v_er_rate := GREATEST(COALESCE((v_cfg ->> 'dsmf_employer_rate')::numeric, 22), 0) / 100.0;
  v_its_rate := GREATEST(COALESCE((v_cfg ->> 'its_rate')::numeric, 0.5), 0) / 100.0;
  v_limit := GREATEST(COALESCE((v_cfg ->> 'non_taxable_salary_limit')::numeric, 0), 0);

  v_first := LEAST(v_gross, 200);
  v_mid := LEAST(GREATEST(v_gross - 200, 0), 7800);
  v_above := GREATEST(v_gross - 8000, 0);

  v_dsmf_ee := ROUND(v_first * v_ee_rate + v_mid * 0.10 + v_above * 0.10, 2);
  v_dsmf_er := ROUND(v_first * v_er_rate + v_mid * 0.15 + v_above * 0.11, 2);
  v_its := ROUND(v_gross * v_its_rate, 2);
  v_taxable := GREATEST(v_gross - v_dsmf_ee - v_its, 0);
  v_pit_base := GREATEST(v_taxable - v_limit, 0);

  v_low_rate := CASE
    WHEN COALESCE(p_year, 2026) >= 2028 THEN 0.07
    WHEN COALESCE(p_year, 2026) >= 2027 THEN 0.05
    ELSE 0.03
  END;
  v_low_tax := ROUND(2500 * v_low_rate, 2);
  v_mid_tax := ROUND(5500 * 0.10, 2);

  IF v_pit_base <= 2500 THEN
    v_pit := ROUND(v_pit_base * v_low_rate, 2);
  ELSIF v_pit_base <= 8000 THEN
    v_pit := ROUND(v_low_tax + (v_pit_base - 2500) * 0.10, 2);
  ELSE
    v_pit := ROUND(v_low_tax + v_mid_tax + (v_pit_base - 8000) * 0.14, 2);
  END IF;

  RETURN QUERY SELECT v_dsmf_ee, v_dsmf_er, v_its, v_its, v_pit, v_taxable;
END;
$function$;

CREATE OR REPLACE FUNCTION public.block_delete_of_posted_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (
    SELECT 1 FROM public.journal_entries je
    WHERE COALESCE(je.document_id, je.source_id) = OLD.id
      AND je.reversed_by IS NULL
      AND je.reversal_of IS NULL
  ) THEN
    RAISE EXCEPTION 'document_has_ledger_entries'
      USING ERRCODE = '42501',
            MESSAGE = 'Müxabirləşməsi olan sənəd silinə bilməz. Ləğv edin — sistem storno yaradacaq.';
  END IF;
  RETURN OLD;
END;
$function$;

CREATE OR REPLACE FUNCTION public.block_journal_entry_delete()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  RAISE EXCEPTION 'ledger_immutable'
    USING ERRCODE = '42501',
          MESSAGE = 'Müxabirləşmə silinə bilməz. Düzəliş üçün storno sənədi yaradın (reverse_journal_entry).';
END;
$function$;

CREATE OR REPLACE FUNCTION public.build_and_validate_sale_stock_demand(p_items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_item JSONB;
  v_product_id UUID;
  v_qty NUMERIC;
  v_polywood_mode TEXT;
  v_skip_stock BOOLEAN;
  v_stock_demand JSONB := '{}'::jsonb;
  v_key TEXT;
  v_stock NUMERIC;
  v_required NUMERIC;
BEGIN
  IF jsonb_typeof(p_items) <> 'array' THEN
    RETURN '{}'::jsonb;
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_product_id := NULLIF(v_item->>'product_id', '')::uuid;
    v_qty := COALESCE(NULLIF(v_item->>'quantity', '')::numeric, 0);
    v_polywood_mode := NULLIF(trim(v_item->>'polywood_sale_mode'), '');
    v_skip_stock := COALESCE((v_item->>'skip_stock')::boolean, false);

    IF v_product_id IS NULL OR v_qty <= 0 OR v_polywood_mode IS NOT NULL OR v_skip_stock THEN
      CONTINUE;
    END IF;

    -- Services carry no stock.
    IF EXISTS (SELECT 1 FROM public.products WHERE id = v_product_id AND is_service) THEN
      CONTINUE;
    END IF;

    v_stock_demand := public.merge_stock_demand(v_stock_demand, v_product_id, v_qty);
  END LOOP;

  FOR v_key IN SELECT jsonb_object_keys(v_stock_demand)
  LOOP
    v_product_id := v_key::uuid;
    v_required := COALESCE((v_stock_demand->>v_key)::numeric, 0);

    SELECT stock INTO v_stock
    FROM public.products
    WHERE id = v_product_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'product_not_found'
        USING ERRCODE = 'P0002', MESSAGE = 'Məhsul tapılmadı: ' || v_key;
    END IF;

    IF COALESCE(v_stock, 0) + 0.000001 < v_required THEN
      RAISE EXCEPTION 'insufficient_stock'
        USING ERRCODE = '22023',
              MESSAGE = format(
                'Stok kifayət etmir (məhsul %s, tələb: %s, mövcud: %s)',
                v_key,
                trim(to_char(v_required, 'FM999999990.00')),
                trim(to_char(COALESCE(v_stock, 0), 'FM999999990.00'))
              );
    END IF;
  END LOOP;

  RETURN v_stock_demand;
END;
$function$;

CREATE OR REPLACE FUNCTION public.can_delegate_invoice_issuer()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM profiles p
    JOIN roles r ON r.id = p.role_id
    WHERE p.id = auth.uid()
      AND COALESCE(p.is_active, true)
      AND r.name IN ('Admin', 'Manager')
  );
$function$;

CREATE OR REPLACE FUNCTION public.check_customer_ar_discrepancies()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_rows JSONB := '[]'::jsonb;
BEGIN
  SELECT COALESCE(jsonb_agg(row_payload ORDER BY customer_name), '[]'::jsonb)
  INTO v_rows
  FROM (
    SELECT jsonb_build_object(
      'customer_id', c.id,
      'customer_name', COALESCE(NULLIF(trim(c.full_name), ''), NULLIF(trim(c.name), ''), NULLIF(trim(c.company_name), ''), c.code, c.id::text),
      'stored_balance', COALESCE(c.balance, 0),
      'ledger_balance', COALESCE(SUM(GREATEST(COALESCE(s.remaining_balance, 0), 0)), 0),
      'delta', COALESCE(c.balance, 0) - COALESCE(SUM(GREATEST(COALESCE(s.remaining_balance, 0), 0)), 0)
    ) AS row_payload,
    COALESCE(NULLIF(trim(c.full_name), ''), NULLIF(trim(c.name), ''), c.code, c.id::text) AS customer_name
    FROM customers c
    LEFT JOIN sales s ON s.customer_id = c.id
    GROUP BY c.id, c.full_name, c.name, c.company_name, c.code, c.balance
    HAVING abs(COALESCE(c.balance, 0) - COALESCE(SUM(GREATEST(COALESCE(s.remaining_balance, 0), 0)), 0)) > 0.01
  ) mismatches;

  RETURN jsonb_build_object(
    'discrepancy_count', jsonb_array_length(v_rows),
    'discrepancies', v_rows
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_payment_permissions(p_user_id uuid, p_type text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF p_type = 'sale' THEN
        RETURN public.user_has_permission(p_user_id, 'can_edit_sales')
            OR public.user_has_permission(p_user_id, 'can_create_invoice')
            OR public.user_has_permission(p_user_id, 'can_manage_finance');
    ELSIF p_type = 'purchase' THEN
        RETURN public.user_has_permission(p_user_id, 'can_edit_purchases')
            OR public.user_has_permission(p_user_id, 'can_manage_finance');
    END IF;
    RETURN false;
END;
$function$;

CREATE OR REPLACE FUNCTION public.coa_credit_for_cash_in(p_category text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_cat TEXT := trim(COALESCE(p_category, ''));
BEGIN
  IF v_cat = 'İlkin Qalıq' THEN
    RETURN '3900';
  END IF;
  IF v_cat IN ('Satış Ödənişi', 'Satış') OR v_cat ILIKE '%satış%' THEN
    RETURN '1200';
  END IF;
  IF v_cat = 'Satış gəliri' THEN
    RETURN '4100';
  END IF;
  RETURN '4990';
END;
$function$;

CREATE OR REPLACE FUNCTION public.coa_debit_for_cash_out(p_category text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE
  v_cat TEXT := trim(COALESCE(p_category, ''));
BEGIN
  IF v_cat = 'İlkin Qalıq' THEN
    RETURN '3900';
  END IF;
  IF v_cat IN ('Alış Ödənişi', 'Alış') OR v_cat ILIKE '%alış%' THEN
    RETURN '2100';
  END IF;
  IF v_cat IN (
    'İcarə', 'Elektrik', 'Yanacaq', 'İnternet', 'Reklam', 'Təmir', 'Maaş', 'Digər',
    'transport', 'delivery', 'installation', 'tools', 'other'
  ) THEN
    RETURN '6100';
  END IF;
  RETURN '6190';
END;
$function$;

CREATE OR REPLACE FUNCTION public.compute_customer_open_ar(p_customer_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE
AS $function$
  SELECT COALESCE(SUM(GREATEST(COALESCE(remaining_balance, 0), 0)), 0)
    + COALESCE((SELECT opening_balance FROM public.customers WHERE id = p_customer_id), 0)
  FROM public.sales
  WHERE customer_id = p_customer_id;
$function$;

CREATE OR REPLACE FUNCTION public.compute_partner_net_balance(p_partner_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    public.compute_partner_open_receivables(p_partner_id)
    - public.compute_partner_open_payables(p_partner_id);
$function$;

CREATE OR REPLACE FUNCTION public.compute_partner_open_payables(p_partner_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(SUM(GREATEST(COALESCE(pu.debt_amount, 0), 0)), 0)
  FROM purchases pu
  WHERE pu.partner_id = p_partner_id
    AND COALESCE(lower(trim(pu.status)), '') NOT IN ('void', 'voided', 'cancelled', 'ləğv edildi', 'legv edildi');
$function$;

CREATE OR REPLACE FUNCTION public.compute_partner_open_receivables(p_partner_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(SUM(GREATEST(COALESCE(s.remaining_balance, 0), 0)), 0)
  FROM sales s
  WHERE s.partner_id = p_partner_id
    AND COALESCE(lower(trim(s.status)), '') NOT IN ('void', 'voided', 'cancelled', 'ləğv edildi', 'legv edildi');
$function$;

CREATE OR REPLACE FUNCTION public.compute_supplier_open_ap(p_supplier_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE
AS $function$
  SELECT COALESCE(SUM(GREATEST(COALESCE(debt_amount, 0), 0)), 0)
    + COALESCE((SELECT opening_balance FROM public.suppliers WHERE id = p_supplier_id), 0)
  FROM public.purchases
  WHERE supplier_id = p_supplier_id;
$function$;

CREATE OR REPLACE FUNCTION public.create_account_atomic(p_code text, p_name text, p_type text, p_opening_balance numeric DEFAULT 0)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account_id UUID;
  v_code TEXT;
  v_name TEXT;
  v_type TEXT;
  v_opening NUMERIC;
BEGIN
  IF NOT (
    public.require_permission('can_manage_finance')
    OR public.require_permission('can_manage_settings')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Hesab yaratmaq üçün icazəniz yoxdur';
  END IF;

  v_name := trim(COALESCE(p_name, ''));
  v_type := trim(COALESCE(p_type, ''));
  v_code := trim(COALESCE(p_code, ''));

  IF v_name = '' THEN
    RAISE EXCEPTION 'invalid_name'
      USING ERRCODE = '22023',
            MESSAGE = 'Hesab adı tələb olunur';
  END IF;

  IF v_type NOT IN ('Kassa', 'Bank') THEN
    RAISE EXCEPTION 'invalid_type'
      USING ERRCODE = '22023',
            MESSAGE = 'Hesab növü Kassa və ya Bank olmalıdır';
  END IF;

  v_opening := GREATEST(COALESCE(p_opening_balance, 0), 0);

  IF v_code = '' THEN
    v_code := 'ACC-' || floor(100 + random() * 900)::int;
  END IF;

  INSERT INTO accounts (code, name, type, balance)
  VALUES (v_code, v_name, v_type, 0)
  RETURNING id INTO v_account_id;

  IF v_opening > 0.0001 THEN
    PERFORM public.post_cash_transaction(
      v_account_id,
      'Mədaxil',
      v_opening,
      'İlkin Qalıq',
      format('İlkin qalıq — %s (%s)', v_name, v_code)
    );
  END IF;

  RETURN v_account_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_inventory_batch(p_product_id uuid, p_document_id uuid, p_document_type text, p_unit_cost numeric, p_quantity numeric)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_batch_id UUID;
  v_qty NUMERIC := COALESCE(p_quantity, 0);
  v_cost NUMERIC := COALESCE(p_unit_cost, 0);
BEGIN
  IF p_product_id IS NULL OR v_qty <= 0 THEN
    RETURN NULL;
  END IF;

  INSERT INTO public.inventory_batches (
    product_id,
    document_id,
    document_type,
    unit_cost,
    initial_qty,
    remaining_qty
  )
  VALUES (
    p_product_id,
    p_document_id,
    COALESCE(NULLIF(trim(p_document_type), ''), 'purchase'),
    GREATEST(v_cost, 0),
    v_qty,
    v_qty
  )
  RETURNING id INTO v_batch_id;

  RETURN v_batch_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_journal_entry(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_lines JSONB;
  v_line JSONB;
  v_entry_id UUID;
  v_entry_no TEXT;
  v_idempotency TEXT;
  v_total_debit NUMERIC := 0;
  v_total_credit NUMERIC := 0;
  v_account_id UUID;
  v_account_code TEXT;
  v_line_account_id UUID;
  v_cash_account_id UUID;
  v_debit NUMERIC;
  v_credit NUMERIC;
  v_idx INT := 0;
  v_document_type TEXT;
  v_document_id UUID;
  v_description TEXT;
  v_date TIMESTAMPTZ;
  v_entry_date DATE;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Journal payload tələb olunur';
  END IF;

  v_idempotency := NULLIF(trim(p_payload->>'idempotency_key'), '');
  IF v_idempotency IS NOT NULL THEN
    SELECT id INTO v_entry_id
    FROM public.journal_entries
    WHERE idempotency_key = v_idempotency
    LIMIT 1;
    IF FOUND THEN
      RETURN v_entry_id;
    END IF;
  END IF;

  v_lines := COALESCE(p_payload->'lines', '[]'::jsonb);
  IF jsonb_typeof(v_lines) <> 'array' OR jsonb_array_length(v_lines) = 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Journal sətirləri tələb olunur';
  END IF;

  FOR v_idx IN 0 .. jsonb_array_length(v_lines) - 1 LOOP
    v_line := v_lines->v_idx;
    v_debit := COALESCE((v_line->>'debit')::numeric, 0);
    v_credit := COALESCE((v_line->>'credit')::numeric, 0);

    IF v_debit < 0 OR v_credit < 0 THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Debet və kredit mənfi ola bilməz';
    END IF;

    IF v_debit > 0 AND v_credit > 0 THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Eyni sətirdə debet və kredit eyni vaxtda ola bilməz';
    END IF;

    v_total_debit := v_total_debit + v_debit;
    v_total_credit := v_total_credit + v_credit;
  END LOOP;

  IF abs(v_total_debit - v_total_credit) > 0.0001 THEN
    RAISE EXCEPTION USING
      ERRCODE = '22023',
      MESSAGE = format('Journal balanssızdir (debet=%s, kredit=%s)', v_total_debit, v_total_credit);
  END IF;

  v_document_type := COALESCE(
    NULLIF(trim(p_payload->>'document_type'), ''),
    NULLIF(trim(p_payload->>'source_type'), ''),
    'manual'
  );
  v_document_id := COALESCE(
    NULLIF(p_payload->>'document_id', '')::uuid,
    NULLIF(p_payload->>'source_id', '')::uuid
  );
  v_description := COALESCE(
    NULLIF(trim(p_payload->>'description'), ''),
    NULLIF(trim(p_payload->>'memo'), '')
  );
  v_date := COALESCE(
    NULLIF(p_payload->>'date', '')::timestamptz,
    NULLIF(p_payload->>'entry_date', '')::date::timestamptz,
    NOW()
  );
  v_entry_date := COALESCE(
    NULLIF(p_payload->>'entry_date', '')::date,
    (v_date AT TIME ZONE 'UTC')::date,
    CURRENT_DATE
  );

  v_entry_no := COALESCE(
    NULLIF(trim(p_payload->>'entry_no'), ''),
    'JE-' || to_char(v_entry_date, 'YYYYMMDD') || '-' || floor(1000 + random() * 9000)::int
  );

  INSERT INTO public.journal_entries (
    entry_no,
    entry_date,
    date,
    source_type,
    source_id,
    document_type,
    document_id,
    description,
    idempotency_key,
    memo,
    created_by
  )
  VALUES (
    v_entry_no,
    v_entry_date,
    v_date,
    v_document_type,
    v_document_id,
    v_document_type,
    v_document_id,
    v_description,
    v_idempotency,
    v_description,
    auth.uid()
  )
  RETURNING id INTO v_entry_id;

  FOR v_idx IN 0 .. jsonb_array_length(v_lines) - 1 LOOP
    v_line := v_lines->v_idx;

    v_line_account_id := NULLIF(v_line->>'account_id', '')::uuid;
    v_cash_account_id := NULLIF(v_line->>'cash_account_id', '')::uuid;
    v_account_id := NULLIF(v_line->>'coa_id', '')::uuid;
    v_account_code := COALESCE(
      NULLIF(trim(v_line->>'account_code'), ''),
      NULLIF(trim(v_line->>'coa_code'), '')
    );

    IF v_account_id IS NULL AND v_account_code IS NOT NULL THEN
      v_account_id := public.resolve_gl_account_id(v_account_code);
    END IF;

    IF v_account_id IS NULL AND v_line_account_id IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.chart_of_accounts WHERE id = v_line_account_id) THEN
      v_account_id := v_line_account_id;
    END IF;

    IF v_cash_account_id IS NULL AND v_line_account_id IS NOT NULL
       AND v_line_account_id IS DISTINCT FROM v_account_id
       AND EXISTS (SELECT 1 FROM public.accounts WHERE id = v_line_account_id) THEN
      v_cash_account_id := v_line_account_id;
    END IF;

    IF v_account_id IS NULL THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0002',
        MESSAGE = format(
          'Hesab tapılmadı: %s',
          COALESCE(v_account_code, v_line->>'coa_id', v_line->>'account_id')
        );
    END IF;

    INSERT INTO public.journal_entry_lines (
      journal_entry_id,
      coa_id,
      debit,
      credit,
      partner_type,
      partner_id,
      account_id,
      line_memo
    )
    VALUES (
      v_entry_id,
      v_account_id,
      COALESCE((v_line->>'debit')::numeric, 0),
      COALESCE((v_line->>'credit')::numeric, 0),
      NULLIF(trim(v_line->>'partner_type'), ''),
      NULLIF(v_line->>'partner_id', '')::uuid,
      v_cash_account_id,
      COALESCE(
        NULLIF(trim(v_line->>'line_memo'), ''),
        NULLIF(trim(v_line->>'memo'), '')
      )
    );
  END LOOP;

  RETURN v_entry_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_manual_expense_transaction(p_category text, p_amount numeric, p_account_id uuid, p_description text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tx_id UUID;
  v_category_id UUID;
  v_desc TEXT;
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount' USING ERRCODE = '22023';
  END IF;
  IF p_account_id IS NULL THEN
    RAISE EXCEPTION 'account_required' USING ERRCODE = '22023';
  END IF;

  v_category_id := resolve_financial_category_id(p_category, 'EXPENSE');
  v_desc := COALESCE(NULLIF(trim(p_description), ''), NULLIF(trim(p_notes), ''), p_category, 'Əl ilə xərc');

  v_tx_id := post_cash_transaction(
    p_account_id,
    'Məxaric',
    p_amount,
    COALESCE(p_category, 'Digər'),
    v_desc,
    NULL,
    'manual_expense',
    NULL
  );

  UPDATE transactions
  SET
    unified_type = 'EXPENSE',
    category_id = v_category_id,
    reference_type = 'manual_expense',
    description = v_desc,
    transaction_date = COALESCE(transaction_date, created_at, NOW()),
    created_by = p_created_by
  WHERE id = v_tx_id;

  RETURN v_tx_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_partner_payment(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idempotency TEXT;
  v_existing public.payments%ROWTYPE;
  v_partner_id UUID;
  v_amount NUMERIC;
  v_payment_type TEXT;
  v_payment_method TEXT;
  v_payment_date TIMESTAMPTZ;
  v_reference_note TEXT;
  v_cash_account_id UUID;
  v_balance NUMERIC;
  v_payment_id UUID;
  v_tx_id UUID;
  v_journal_id UUID;
  v_tx_type TEXT;
  v_category TEXT;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Ödəniş payload tələb olunur';
  END IF;

  IF NOT public.require_permission('can_manage_finance') THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501', MESSAGE = 'Maliyyə əməliyyatı üçün icazəniz yoxdur';
  END IF;

  v_idempotency := NULLIF(trim(p_payload->>'idempotency_key'), '');
  IF v_idempotency IS NOT NULL THEN
    SELECT * INTO v_existing
    FROM public.payments
    WHERE idempotency_key = v_idempotency
    LIMIT 1;

    IF FOUND THEN
      RETURN jsonb_build_object(
        'success', true,
        'payment_id', v_existing.id,
        'journal_entry_id', v_existing.journal_entry_id,
        'transaction_id', v_existing.transaction_id,
        'idempotent', true
      );
    END IF;
  END IF;

  v_partner_id := NULLIF(p_payload->>'partner_id', '')::uuid;
  v_amount := COALESCE(NULLIF(p_payload->>'amount', '')::numeric, 0);
  v_payment_type := lower(trim(COALESCE(p_payload->>'payment_type', '')));
  v_payment_method := lower(trim(COALESCE(p_payload->>'payment_method', 'cash')));
  v_payment_date := COALESCE(NULLIF(p_payload->>'payment_date', '')::timestamptz, NOW());
  v_reference_note := NULLIF(trim(p_payload->>'reference_note'), '');
  v_cash_account_id := NULLIF(p_payload->>'cash_account_id', '')::uuid;

  IF v_partner_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Tərəfdaş seçilməlidir';
  END IF;

  IF v_amount <= 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Məbləğ sıfırdan böyük olmalıdır';
  END IF;

  IF v_payment_type NOT IN ('in', 'out') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'payment_type «in» və ya «out» olmalıdır';
  END IF;

  IF v_payment_method NOT IN ('cash', 'bank') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'payment_method «cash» və ya «bank» olmalıdır';
  END IF;

  PERFORM id FROM public.partners WHERE id = v_partner_id AND is_deleted = FALSE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'partner_not_found' USING ERRCODE = 'P0002', MESSAGE = 'Tərəfdaş tapılmadı';
  END IF;

  IF v_cash_account_id IS NULL THEN
    v_cash_account_id := public.resolve_default_cash_account_id(v_payment_method);
  END IF;

  IF v_cash_account_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Kassa/bank hesabı tapılmadı';
  END IF;

  SELECT balance INTO v_balance
  FROM public.accounts
  WHERE id = v_cash_account_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_not_found' USING ERRCODE = 'P0002', MESSAGE = 'Kassa/bank hesabı tapılmadı';
  END IF;

  IF v_payment_type = 'out' AND COALESCE(v_balance, 0) + 0.0001 < v_amount THEN
    RAISE EXCEPTION 'insufficient_balance' USING ERRCODE = '22023', MESSAGE = 'Hesab balansı kifayət etmir';
  END IF;

  INSERT INTO public.payments (
    payment_date,
    partner_id,
    amount,
    payment_type,
    payment_method,
    reference_note,
    cash_account_id,
    idempotency_key,
    created_by
  )
  VALUES (
    v_payment_date,
    v_partner_id,
    v_amount,
    v_payment_type,
    v_payment_method,
    v_reference_note,
    v_cash_account_id,
    v_idempotency,
    auth.uid()
  )
  RETURNING id INTO v_payment_id;

  v_tx_type := CASE WHEN v_payment_type = 'in' THEN 'Mədaxil' ELSE 'Məxaric' END;
  v_category := CASE
    WHEN v_payment_type = 'in' THEN 'Tərəfdaşdan mədaxil'
    ELSE 'Tərəfdaşa məxaric'
  END;

  INSERT INTO public.transactions (
    account_id,
    amount,
    type,
    unified_type,
    category,
    notes,
    description,
    transaction_date,
    created_at,
    reference_type,
    reference_id,
    source_type,
    source_id
  )
  VALUES (
    v_cash_account_id,
    v_amount,
    v_tx_type,
    CASE WHEN v_payment_type = 'in' THEN 'INCOME' ELSE 'EXPENSE' END,
    v_category,
    COALESCE(v_reference_note, v_category),
    COALESCE(v_reference_note, v_category),
    v_payment_date,
    NOW(),
    'partner_payment',
    v_payment_id,
    'partner_payment',
    v_payment_id
  )
  RETURNING id INTO v_tx_id;

  IF v_payment_type = 'in' THEN
    UPDATE public.accounts
    SET balance = COALESCE(v_balance, 0) + v_amount
    WHERE id = v_cash_account_id;
  ELSE
    UPDATE public.accounts
    SET balance = COALESCE(v_balance, 0) - v_amount
    WHERE id = v_cash_account_id;
  END IF;

  v_journal_id := public.post_partner_payment_gl_journal(
    v_payment_id,
    v_partner_id,
    v_amount,
    v_payment_type,
    v_payment_method,
    v_cash_account_id,
    v_reference_note
  );

  UPDATE public.payments
  SET journal_entry_id = v_journal_id,
      transaction_id = v_tx_id
  WHERE id = v_payment_id;

  UPDATE public.transactions
  SET journal_entry_id = v_journal_id
  WHERE id = v_tx_id;

  PERFORM public.refresh_partner_linked_balances(v_partner_id);

  RETURN jsonb_build_object(
    'success', true,
    'payment_id', v_payment_id,
    'journal_entry_id', v_journal_id,
    'transaction_id', v_tx_id
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_product_with_bom_atomic(p_product jsonb, p_bom_rows jsonb DEFAULT '[]'::jsonb, p_is_composite boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_product public.products;
  v_row JSONB;
  v_component_id UUID;
  v_quantity NUMERIC;
  v_bom_count INT := 0;
  v_is_service BOOLEAN := COALESCE((p_product->>'is_service')::boolean, false);
BEGIN
  IF p_product IS NULL OR COALESCE(btrim(p_product->>'name'), '') = '' THEN
    RAISE EXCEPTION 'product_name_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Məhsul adı tələb olunur';
  END IF;

  INSERT INTO public.products (
    code,
    name,
    category,
    subcategory,
    unit,
    buy_price,
    sell_price,
    price_wholesale,
    price_distributor,
    stock,
    min_stock,
    min_stock_level,
    barcode,
    qr_code,
    extra_info,
    category_id,
    is_dimensional,
    is_service,
    is_composite,
    base_length,
    base_width
  )
  VALUES (
    COALESCE(
      NULLIF(btrim(p_product->>'code'), ''),
      'PRD-' || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8))
    ),
    btrim(p_product->>'name'),
    COALESCE(NULLIF(btrim(p_product->>'category'), ''), 'Ümumi'),
    NULLIF(btrim(p_product->>'subcategory'), ''),
    COALESCE(NULLIF(btrim(p_product->>'unit'), ''), 'Ədəd'),
    COALESCE((p_product->>'buy_price')::numeric, 0),
    COALESCE((p_product->>'sell_price')::numeric, 0),
    NULLIF(p_product->>'price_wholesale', '')::numeric,
    NULLIF(p_product->>'price_distributor', '')::numeric,
    CASE WHEN v_is_service THEN 0 ELSE COALESCE((p_product->>'stock')::numeric, 0) END,
    CASE WHEN v_is_service THEN 0 ELSE COALESCE((p_product->>'min_stock')::numeric, 0) END,
    CASE
      WHEN v_is_service THEN 0
      ELSE COALESCE(
        (p_product->>'min_stock_level')::numeric,
        (p_product->>'min_stock')::numeric,
        0
      )
    END,
    NULLIF(btrim(p_product->>'barcode'), ''),
    NULLIF(btrim(p_product->>'qr_code'), ''),
    NULLIF(btrim(p_product->>'extra_info'), ''),
    NULLIF(p_product->>'category_id', '')::uuid,
    COALESCE((p_product->>'is_dimensional')::boolean, false),
    v_is_service,
    CASE WHEN v_is_service THEN false ELSE COALESCE(p_is_composite, false) END,
    NULLIF(p_product->>'base_length', '')::numeric,
    NULLIF(p_product->>'base_width', '')::numeric
  )
  RETURNING * INTO v_product;

  IF p_is_composite AND NOT v_is_service THEN
    FOR v_row IN
      SELECT value FROM jsonb_array_elements(COALESCE(p_bom_rows, '[]'::jsonb))
    LOOP
      v_component_id := NULLIF(v_row->>'component_product_id', '')::uuid;
      v_quantity := COALESCE((v_row->>'quantity')::numeric, 0);

      IF v_component_id IS NULL OR v_quantity <= 0 THEN
        CONTINUE;
      END IF;

      IF v_component_id = v_product.id THEN
        DELETE FROM public.products WHERE id = v_product.id;
        RAISE EXCEPTION 'bom_self_reference'
          USING ERRCODE = '22023',
                MESSAGE = 'Komplekt komponenti öz məhsuluna bərabər ola bilməz';
      END IF;

      INSERT INTO public.product_bom (parent_product_id, component_product_id, quantity)
      VALUES (v_product.id, v_component_id, v_quantity);

      v_bom_count := v_bom_count + 1;
    END LOOP;

    IF v_bom_count = 0 THEN
      DELETE FROM public.products WHERE id = v_product.id;
      RAISE EXCEPTION 'bom_rows_required'
        USING ERRCODE = '22023',
              MESSAGE = 'Komplekt üçün ən azı bir komponent tələb olunur';
    END IF;
  END IF;

  RETURN to_jsonb(v_product);
END;
$function$;

CREATE OR REPLACE FUNCTION public.create_safety_stock_request(p_product_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_product RECORD;
  v_min NUMERIC;
  v_stock NUMERIC;
  v_qty NUMERIC;
  v_existing UUID;
  v_request_id UUID;
  v_no TEXT;
  v_cfg JSONB;
  v_auto BOOLEAN;
  v_lead INT;
BEGIN
  SELECT value INTO v_cfg
    FROM public.system_settings
   WHERE key = 'procurement_config';

  v_auto := COALESCE((v_cfg ->> 'auto_create_purchase_request')::boolean, true);
  IF NOT v_auto THEN
    RETURN NULL;
  END IF;

  v_lead := GREATEST(COALESCE((v_cfg ->> 'default_lead_time_days')::int, 7), 0);

  SELECT
    id,
    code,
    name,
    unit,
    COALESCE(is_service, FALSE) AS is_service,
    COALESCE(stock, 0) AS stock,
    COALESCE(min_stock_level, min_stock, 0) AS min_level
    INTO v_product
    FROM public.products
   WHERE id = p_product_id;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  IF v_product.is_service THEN
    RETURN NULL;
  END IF;

  v_min := COALESCE(v_product.min_level, 0);
  v_stock := COALESCE(v_product.stock, 0);

  IF v_min <= 0 OR v_stock > v_min THEN
    RETURN NULL;
  END IF;

  SELECT id
    INTO v_existing
    FROM public.purchase_requests
   WHERE product_id = p_product_id
     AND status IN ('auto_triggered', 'pending', 'ordered')
     AND source = 'safety_stock'
   LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN v_existing;
  END IF;

  v_qty := GREATEST(v_min, v_min - v_stock, 1);
  v_no := 'ASR-' || to_char(NOW(), 'YYYYMMDD') || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 6);

  INSERT INTO public.purchase_requests (
    request_no,
    production_order_id,
    product_id,
    product_code,
    product_name,
    warehouse_id,
    quantity,
    unit,
    status,
    source,
    notes
  )
  VALUES (
    v_no,
    NULL,
    v_product.id,
    v_product.code,
    v_product.name,
    NULL,
    v_qty,
    COALESCE(v_product.unit, 'Ədəd'),
    'auto_triggered',
    'safety_stock',
    format(
      'Avtomatik: stok %s ≤ minimum hədd %s. Təxmini çatdırılma: %s gün',
      to_char(v_stock, 'FM999999990.00'),
      to_char(v_min, 'FM999999990.00'),
      v_lead::text
    )
  )
  RETURNING id INTO v_request_id;

  RETURN v_request_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.current_user_department()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT e.department
  FROM public.profiles p
  LEFT JOIN public.employees e ON e.id = p.employee_id
  WHERE p.id = auth.uid()
    AND COALESCE(p.is_active, TRUE)
  LIMIT 1;
$function$;

