CREATE OR REPLACE FUNCTION public.delete_document_cash_transactions(p_source_type text, p_source_id uuid, p_doc_label text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_tx RECORD;
  v_deleted INT := 0;
  v_account_ids UUID[] := ARRAY[]::UUID[];
  v_label TEXT;
BEGIN
  v_label := trim(COALESCE(p_doc_label, ''));

  FOR v_tx IN
    SELECT id, account_id
    FROM transactions
    WHERE (
      (p_source_id IS NOT NULL AND source_type = p_source_type AND source_id = p_source_id)
      OR (
        v_label <> ''
        AND COALESCE(source_type, '') = ''
        AND COALESCE(source_id::text, '') = ''
        AND notes ILIKE '%' || v_label || '%'
      )
    )
  LOOP
    DELETE FROM transactions WHERE id = v_tx.id;
    v_deleted := v_deleted + 1;
    IF v_tx.account_id IS NOT NULL
       AND NOT v_tx.account_id = ANY (v_account_ids) THEN
      v_account_ids := array_append(v_account_ids, v_tx.account_id);
    END IF;
  END LOOP;

  PERFORM public.reconcile_accounts_for_transactions(v_account_ids);
  RETURN v_deleted;
END;
$function$;

CREATE OR REPLACE FUNCTION public.effective_user_permissions()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(r.permissions, '{}'::jsonb) || COALESCE(p.permission_overrides, '{}'::jsonb)
  FROM public.profiles p
  LEFT JOIN public.roles r ON r.id = p.role_id
  WHERE p.id = auth.uid()
    AND COALESCE(p.is_active, TRUE)
  LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.employee_is_payable(p_status text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT lower(btrim(COALESCE(p_status, 'active'))) IN ('', 'active', 'aktiv', 'активный', 'актив');
$function$;

CREATE OR REPLACE FUNCTION public.enforce_sale_invoice_audit_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor UUID := auth.uid();
  v_delegate BOOLEAN;
  v_profile_id UUID;
  v_employee_id UUID;
  v_display_name TEXT;
BEGIN
  IF v_actor IS NULL THEN
    RETURN NEW;
  END IF;

  NEW.created_by := v_actor;
  v_delegate := public.can_delegate_invoice_issuer();

  IF v_delegate AND NEW.issued_by IS NOT NULL AND NEW.issued_by <> v_actor THEN
    SELECT p.id, p.employee_id, COALESCE(NULLIF(trim(e.full_name), ''), NULLIF(trim(p.full_name), ''), '')
    INTO v_profile_id, v_employee_id, v_display_name
    FROM profiles p
    LEFT JOIN employees e ON e.id = p.employee_id
    WHERE p.id = NEW.issued_by
      AND COALESCE(p.is_active, true);

    IF NOT FOUND THEN
      NEW.issued_by := v_actor;
    ELSE
      IF NEW.seller_id IS NULL AND v_employee_id IS NOT NULL THEN
        NEW.seller_id := v_employee_id;
      END IF;
      IF COALESCE(NULLIF(trim(NEW.seller_name), ''), '') = '' AND v_display_name <> '' THEN
        NEW.seller_name := v_display_name;
      END IF;
    END IF;
  ELSIF v_delegate AND NEW.seller_id IS NOT NULL THEN
    SELECT p.id, COALESCE(NULLIF(trim(e.full_name), ''), NULLIF(trim(p.full_name), ''), '')
    INTO v_profile_id, v_display_name
    FROM profiles p
    LEFT JOIN employees e ON e.id = p.employee_id
    WHERE p.employee_id = NEW.seller_id
      AND COALESCE(p.is_active, true)
    ORDER BY p.created_at
    LIMIT 1;

    NEW.issued_by := COALESCE(v_profile_id, v_actor);
    IF COALESCE(NULLIF(trim(NEW.seller_name), ''), '') = '' AND v_display_name <> '' THEN
      NEW.seller_name := v_display_name;
    END IF;
  ELSE
    NEW.issued_by := v_actor;

    SELECT p.employee_id, COALESCE(NULLIF(trim(e.full_name), ''), NULLIF(trim(p.full_name), ''), '')
    INTO v_employee_id, v_display_name
    FROM profiles p
    LEFT JOIN employees e ON e.id = p.employee_id
    WHERE p.id = v_actor;

    IF NOT v_delegate THEN
      IF v_employee_id IS NOT NULL THEN
        NEW.seller_id := v_employee_id;
      END IF;
      IF COALESCE(NULLIF(trim(NEW.seller_name), ''), '') = '' AND v_display_name <> '' THEN
        NEW.seller_name := v_display_name;
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.ensure_inventory_barcode()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.barcode IS NULL OR btrim(NEW.barcode) = '' THEN
    NEW.barcode := CASE TG_TABLE_NAME
      WHEN 'polywood_pieces' THEN 'PW'
      ELSE 'DG'
    END || upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 11));
  END IF;
  IF NEW.qr_code IS NULL OR btrim(NEW.qr_code) = '' THEN
    NEW.qr_code := NEW.barcode;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.ensure_partner_for_customer()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM partners p WHERE p.customer_id = NEW.id) THEN
    INSERT INTO partners (
      name, full_name, company_name, phone, address, voen, entity_type, code,
      is_customer, is_supplier, customer_id
    ) VALUES (
      COALESCE(NULLIF(trim(NEW.full_name), ''), NULLIF(trim(NEW.name), ''), NULLIF(trim(NEW.company_name), ''), 'Partner'),
      NEW.full_name,
      NEW.company_name,
      NEW.phone,
      NEW.address,
      NEW.voen,
      COALESCE(NEW.entity_type, 'physical'),
      NEW.code,
      TRUE,
      FALSE,
      NEW.id
    );
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.ensure_partner_for_supplier()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM partners p WHERE p.supplier_id = NEW.id) THEN
    INSERT INTO partners (
      name, full_name, company_name, phone, address, voen, entity_type, code,
      is_customer, is_supplier, supplier_id
    ) VALUES (
      COALESCE(NULLIF(trim(NEW.full_name), ''), NULLIF(trim(NEW.company_name), ''), 'Partner'),
      NEW.full_name,
      NEW.company_name,
      NEW.phone,
      NEW.address,
      NEW.voen,
      COALESCE(NEW.entity_type, 'physical'),
      NEW.code,
      FALSE,
      TRUE,
      NEW.id
    );
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.fifo_deplete_product(p_product_id uuid, p_quantity numeric, p_sale_id uuid, p_sale_item_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_remaining NUMERIC := COALESCE(p_quantity, 0);
  v_batch RECORD;
  v_take NUMERIC;
  v_line_cogs NUMERIC := 0;
  v_fallback_cost NUMERIC := 0;
BEGIN
  IF p_product_id IS NULL OR v_remaining <= 0 THEN
    RETURN 0;
  END IF;

  FOR v_batch IN
    SELECT id, remaining_qty, unit_cost
    FROM public.inventory_batches
    WHERE product_id = p_product_id
      AND remaining_qty > 0
    ORDER BY created_at ASC, id ASC
    FOR UPDATE
  LOOP
    EXIT WHEN v_remaining <= 0.0001;

    v_take := LEAST(v_remaining, v_batch.remaining_qty);

    UPDATE public.inventory_batches
    SET remaining_qty = remaining_qty - v_take
    WHERE id = v_batch.id;

    INSERT INTO public.inventory_batch_consumptions (
      sale_id,
      sale_item_id,
      batch_id,
      product_id,
      quantity,
      unit_cost,
      cogs_amount
    )
    VALUES (
      p_sale_id,
      p_sale_item_id,
      v_batch.id,
      p_product_id,
      v_take,
      v_batch.unit_cost,
      ROUND(v_take * v_batch.unit_cost, 2)
    );

    v_line_cogs := v_line_cogs + ROUND(v_take * v_batch.unit_cost, 2);
    v_remaining := v_remaining - v_take;
  END LOOP;

  IF v_remaining > 0.0001 THEN
    SELECT COALESCE(buy_price, 0) INTO v_fallback_cost
    FROM public.products
    WHERE id = p_product_id;

    IF COALESCE(v_fallback_cost, 0) <= 0 THEN
      RAISE EXCEPTION 'insufficient_fifo_batches'
        USING ERRCODE = '22023',
              MESSAGE = format(
                'FIFO batch stoku kifayət etmir (məhsul %s, qalıq miqdar %s)',
                p_product_id,
                trim(to_char(v_remaining, 'FM999999990.00'))
              );
    END IF;

    INSERT INTO public.inventory_batch_consumptions (
      sale_id,
      sale_item_id,
      batch_id,
      product_id,
      quantity,
      unit_cost,
      cogs_amount
    )
    VALUES (
      p_sale_id,
      p_sale_item_id,
      NULL,
      p_product_id,
      v_remaining,
      v_fallback_cost,
      ROUND(v_remaining * v_fallback_cost, 2)
    );

    v_line_cogs := v_line_cogs + ROUND(v_remaining * v_fallback_cost, 2);
  END IF;

  RETURN ROUND(v_line_cogs, 2);
END;
$function$;

CREATE OR REPLACE FUNCTION public.find_erp_event_by_idempotency(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row public.erp_events%ROWTYPE;
BEGIN
  IF p_key IS NULL OR trim(p_key) = '' THEN
    RETURN NULL;
  END IF;

  SELECT * INTO v_row
  FROM public.erp_events
  WHERE idempotency_key = trim(p_key)
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN NULL;
  END IF;

  RETURN jsonb_build_object(
    'event_id', v_row.id,
    'event_type', v_row.event_type,
    'source_table', v_row.source_table,
    'source_id', v_row.source_id,
    'journal_entry_id', v_row.journal_entry_id,
    'result', COALESCE(v_row.result, '{}'::jsonb),
    'already_processed', true
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_batch_available_stock(p_product_id uuid)
 RETURNS numeric
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (
      SELECT SUM(ib.remaining_qty)
      FROM public.inventory_batches ib
      WHERE ib.product_id = p_product_id
        AND ib.remaining_qty > 0
    ),
    (
      SELECT COALESCE(p.stock, 0)
      FROM public.products p
      WHERE p.id = p_product_id
    ),
    0
  );
$function$;

CREATE OR REPLACE FUNCTION public.get_composite_available_stock(p_product_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_min NUMERIC;
BEGIN
  SELECT MIN(
    FLOOR(
      public.get_batch_available_stock(pb.component_product_id)
      / GREATEST(pb.quantity, 0.0001)
    )
  )
  INTO v_min
  FROM public.product_bom pb
  WHERE pb.parent_product_id = p_product_id;

  IF v_min IS NULL THEN
    RETURN 0;
  END IF;

  RETURN GREATEST(v_min, 0);
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_gl_trial_balance(p_start_date date, p_end_date date)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH movements AS (
    SELECT
      coa.id AS account_id,
      coa.code,
      coa.name,
      coa.account_type,
      COALESCE(SUM(
        CASE WHEN public.journal_entry_date(je) < p_start_date THEN jel.debit ELSE 0 END
      ), 0) AS open_debit_raw,
      COALESCE(SUM(
        CASE WHEN public.journal_entry_date(je) < p_start_date THEN jel.credit ELSE 0 END
      ), 0) AS open_credit_raw,
      COALESCE(SUM(
        CASE
          WHEN public.journal_entry_date(je) BETWEEN p_start_date AND p_end_date THEN jel.debit
          ELSE 0
        END
      ), 0) AS period_debit,
      COALESCE(SUM(
        CASE
          WHEN public.journal_entry_date(je) BETWEEN p_start_date AND p_end_date THEN jel.credit
          ELSE 0
        END
      ), 0) AS period_credit
    FROM public.chart_of_accounts coa
    LEFT JOIN public.journal_entry_lines jel ON jel.coa_id = coa.id
    LEFT JOIN public.journal_entries je ON je.id = jel.journal_entry_id
    WHERE coa.is_active = true
    GROUP BY coa.id, coa.code, coa.name, coa.account_type
  ),
  computed AS (
    SELECT
      account_id,
      code,
      name,
      account_type,
      period_debit,
      period_credit,
      (open_debit_raw - open_credit_raw) AS open_net,
      (open_debit_raw + period_debit) - (open_credit_raw + period_credit) AS closing_net
    FROM movements
  ),
  final_rows AS (
    SELECT
      account_id,
      code,
      name,
      account_type,
      ROUND(GREATEST(open_net, 0), 2)      AS initial_debit,
      ROUND(GREATEST(-open_net, 0), 2)     AS initial_credit,
      ROUND(period_debit, 2)               AS period_debit,
      ROUND(period_credit, 2)              AS period_credit,
      ROUND(GREATEST(closing_net, 0), 2)   AS closing_debit,
      ROUND(GREATEST(-closing_net, 0), 2)  AS closing_credit
    FROM computed
  )
  SELECT jsonb_build_object(
    'start_date', p_start_date,
    'end_date', p_end_date,
    'rows', COALESCE(
      (
        SELECT jsonb_agg(row_to_json(r)::jsonb ORDER BY r.code)
        FROM final_rows r
      ),
      '[]'::jsonb
    ),
    'totals', (
      SELECT jsonb_build_object(
        'initial_debit', ROUND(COALESCE(SUM(initial_debit), 0), 2),
        'initial_credit', ROUND(COALESCE(SUM(initial_credit), 0), 2),
        'period_debit', ROUND(COALESCE(SUM(period_debit), 0), 2),
        'period_credit', ROUND(COALESCE(SUM(period_credit), 0), 2),
        'closing_debit', ROUND(COALESCE(SUM(closing_debit), 0), 2),
        'closing_credit', ROUND(COALESCE(SUM(closing_credit), 0), 2)
      )
      FROM final_rows
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.get_inventory_turnover_report(p_start_date date, p_end_date date, p_category_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  WITH inbound AS (
    SELECT
      ib.product_id,
      COALESCE(SUM(
        CASE WHEN (ib.created_at AT TIME ZONE 'UTC')::date < p_start_date THEN ib.initial_qty ELSE 0 END
      ), 0) AS inbound_qty_before,
      COALESCE(SUM(
        CASE
          WHEN (ib.created_at AT TIME ZONE 'UTC')::date BETWEEN p_start_date AND p_end_date
            THEN ib.initial_qty
          ELSE 0
        END
      ), 0) AS inbound_qty_period,
      COALESCE(SUM(
        CASE WHEN (ib.created_at AT TIME ZONE 'UTC')::date < p_start_date THEN ib.initial_qty * ib.unit_cost ELSE 0 END
      ), 0) AS inbound_value_before,
      COALESCE(SUM(
        CASE
          WHEN (ib.created_at AT TIME ZONE 'UTC')::date BETWEEN p_start_date AND p_end_date
            THEN ib.initial_qty * ib.unit_cost
          ELSE 0
        END
      ), 0) AS inbound_value_period
    FROM public.inventory_batches ib
    GROUP BY ib.product_id
  ),
  outbound AS (
    SELECT
      ibc.product_id,
      COALESCE(SUM(
        CASE WHEN (ibc.created_at AT TIME ZONE 'UTC')::date < p_start_date THEN ibc.quantity ELSE 0 END
      ), 0) AS outbound_qty_before,
      COALESCE(SUM(
        CASE
          WHEN (ibc.created_at AT TIME ZONE 'UTC')::date BETWEEN p_start_date AND p_end_date
            THEN ibc.quantity
          ELSE 0
        END
      ), 0) AS outbound_qty_period,
      COALESCE(SUM(
        CASE WHEN (ibc.created_at AT TIME ZONE 'UTC')::date < p_start_date THEN ibc.cogs_amount ELSE 0 END
      ), 0) AS outbound_value_before,
      COALESCE(SUM(
        CASE
          WHEN (ibc.created_at AT TIME ZONE 'UTC')::date BETWEEN p_start_date AND p_end_date
            THEN ibc.cogs_amount
          ELSE 0
        END
      ), 0) AS outbound_value_period
    FROM public.inventory_batch_consumptions ibc
    GROUP BY ibc.product_id
  ),
  combined AS (
    SELECT
      p.id AS product_id,
      COALESCE(p.code, '') AS product_code,
      COALESCE(p.name, '') AS product_name,
      COALESCE(p.unit, 'ədəd') AS unit,
      p.category_id,
      COALESCE(c.name, p.category, '') AS category_name,
      GREATEST(COALESCE(i.inbound_qty_before, 0) - COALESCE(o.outbound_qty_before, 0), 0) AS initial_qty,
      GREATEST(COALESCE(i.inbound_value_before, 0) - COALESCE(o.outbound_value_before, 0), 0) AS initial_value,
      COALESCE(i.inbound_qty_period, 0) AS inbound_qty,
      COALESCE(i.inbound_value_period, 0) AS inbound_value,
      COALESCE(o.outbound_qty_period, 0) AS outbound_qty,
      COALESCE(o.outbound_value_period, 0) AS outbound_value
    FROM public.products p
    LEFT JOIN public.categories c ON c.id = p.category_id
    LEFT JOIN inbound i ON i.product_id = p.id
    LEFT JOIN outbound o ON o.product_id = p.id
    WHERE (p_category_id IS NULL OR p.category_id = p_category_id)
  ),
  final_rows AS (
    SELECT
      product_id,
      product_code,
      product_name,
      unit,
      category_id,
      category_name,
      ROUND(initial_qty, 4) AS initial_qty,
      ROUND(initial_value, 2) AS initial_value,
      ROUND(inbound_qty, 4) AS inbound_qty,
      ROUND(inbound_value, 2) AS inbound_value,
      ROUND(outbound_qty, 4) AS outbound_qty,
      ROUND(outbound_value, 2) AS outbound_value,
      ROUND(GREATEST(initial_qty + inbound_qty - outbound_qty, 0), 4) AS closing_qty,
      ROUND(GREATEST(initial_value + inbound_value - outbound_value, 0), 2) AS closing_value
    FROM combined
    WHERE
      initial_qty > 0.0001
      OR inbound_qty > 0.0001
      OR outbound_qty > 0.0001
      OR GREATEST(initial_qty + inbound_qty - outbound_qty, 0) > 0.0001
  )
  SELECT jsonb_build_object(
    'start_date', p_start_date,
    'end_date', p_end_date,
    'category_id', p_category_id,
    'rows', COALESCE(
      (SELECT jsonb_agg(row_to_json(r)::jsonb ORDER BY r.product_code, r.product_name) FROM final_rows r),
      '[]'::jsonb
    ),
    'totals', (
      SELECT jsonb_build_object(
        'initial_qty', ROUND(COALESCE(SUM(initial_qty), 0), 4),
        'initial_value', ROUND(COALESCE(SUM(initial_value), 0), 2),
        'inbound_qty', ROUND(COALESCE(SUM(inbound_qty), 0), 4),
        'inbound_value', ROUND(COALESCE(SUM(inbound_value), 0), 2),
        'outbound_qty', ROUND(COALESCE(SUM(outbound_qty), 0), 4),
        'outbound_value', ROUND(COALESCE(SUM(outbound_value), 0), 2),
        'closing_qty', ROUND(COALESCE(SUM(closing_qty), 0), 4),
        'closing_value', ROUND(COALESCE(SUM(closing_value), 0), 2)
      )
      FROM final_rows
    )
  );
$function$;

CREATE OR REPLACE FUNCTION public.get_partner_reconciliation_act(p_partner_id uuid, p_start_date date, p_end_date date)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner RECORD;
  v_customer_id UUID;
  v_supplier_id UUID;
  v_initial_balance NUMERIC := 0;
  v_closing_balance NUMERIC := 0;
  v_lines JSONB;
BEGIN
  SELECT id, name, full_name, company_name, customer_id, supplier_id
  INTO v_partner
  FROM public.partners
  WHERE id = p_partner_id AND is_deleted = FALSE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'partner_not_found'
      USING ERRCODE = '22023', MESSAGE = 'Tərəfdaş tapılmadı';
  END IF;

  v_customer_id := v_partner.customer_id;
  v_supplier_id := v_partner.supplier_id;

  SELECT COALESCE(SUM(our_debit - our_credit), 0)
  INTO v_initial_balance
  FROM (
    SELECT ROUND(COALESCE(s.total_amount, 0), 2) AS our_debit, 0::numeric AS our_credit
    FROM public.sales s
    WHERE (
      s.partner_id = p_partner_id
      OR (v_customer_id IS NOT NULL AND s.customer_id = v_customer_id)
    )
      AND COALESCE(s.doc_date, (s.created_at AT TIME ZONE 'UTC')::date) < p_start_date
      AND COALESCE(s.status, '') NOT IN ('void', 'cancelled', 'deleted')

    UNION ALL

    SELECT 0::numeric, ROUND(COALESCE(p.total_amount, 0), 2)
    FROM public.purchases p
    WHERE (
      p.partner_id = p_partner_id
      OR (v_supplier_id IS NOT NULL AND p.supplier_id = v_supplier_id)
    )
      AND COALESCE(p.doc_date, (p.created_at AT TIME ZONE 'UTC')::date) < p_start_date
      AND COALESCE(p.status, '') NOT IN ('void', 'cancelled', 'deleted')

    UNION ALL

    SELECT
      CASE WHEN pay.payment_type = 'out' THEN ROUND(pay.amount, 2) ELSE 0 END,
      CASE WHEN pay.payment_type = 'in' THEN ROUND(pay.amount, 2) ELSE 0 END
    FROM public.payments pay
    WHERE pay.partner_id = p_partner_id
      AND (pay.payment_date AT TIME ZONE 'UTC')::date < p_start_date
  ) opening_docs;

  v_initial_balance := ROUND(v_initial_balance, 2);

  WITH doc_lines AS (
    SELECT
      COALESCE(s.doc_date, (s.created_at AT TIME ZONE 'UTC')::date) AS entry_date,
      COALESCE(s.doc_no, s.id::text) AS document_no,
      'invoice'::text AS document_type,
      ROUND(COALESCE(s.total_amount, 0), 2) AS our_debit,
      0::numeric AS our_credit,
      1 AS sort_order
    FROM public.sales s
    WHERE (
      s.partner_id = p_partner_id
      OR (v_customer_id IS NOT NULL AND s.customer_id = v_customer_id)
    )
      AND COALESCE(s.doc_date, (s.created_at AT TIME ZONE 'UTC')::date) BETWEEN p_start_date AND p_end_date
      AND COALESCE(s.status, '') NOT IN ('void', 'cancelled', 'deleted')

    UNION ALL

    SELECT
      COALESCE(p.doc_date, (p.created_at AT TIME ZONE 'UTC')::date),
      COALESCE(p.invoice_number, p.id::text),
      'bill'::text,
      0::numeric,
      ROUND(COALESCE(p.total_amount, 0), 2),
      2
    FROM public.purchases p
    WHERE (
      p.partner_id = p_partner_id
      OR (v_supplier_id IS NOT NULL AND p.supplier_id = v_supplier_id)
    )
      AND COALESCE(p.doc_date, (p.created_at AT TIME ZONE 'UTC')::date) BETWEEN p_start_date AND p_end_date
      AND COALESCE(p.status, '') NOT IN ('void', 'cancelled', 'deleted')

    UNION ALL

    SELECT
      (pay.payment_date AT TIME ZONE 'UTC')::date,
      COALESCE(NULLIF(trim(pay.reference_note), ''), pay.id::text),
      CASE WHEN pay.payment_type = 'in' THEN 'payment_receipt' ELSE 'payment_disbursement' END,
      CASE WHEN pay.payment_type = 'out' THEN ROUND(pay.amount, 2) ELSE 0 END,
      CASE WHEN pay.payment_type = 'in' THEN ROUND(pay.amount, 2) ELSE 0 END,
      3
    FROM public.payments pay
    WHERE pay.partner_id = p_partner_id
      AND (pay.payment_date AT TIME ZONE 'UTC')::date BETWEEN p_start_date AND p_end_date
  ),
  ordered AS (
    SELECT
      entry_date,
      document_no,
      document_type,
      our_debit,
      our_credit,
      SUM(our_debit - our_credit) OVER (
        ORDER BY entry_date, sort_order, document_no
        ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
      ) AS period_delta
    FROM doc_lines
  )
  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'entry_date', entry_date,
        'document_no', document_no,
        'document_type', document_type,
        'our_debit', our_debit,
        'our_credit', our_credit,
        'running_balance', ROUND(v_initial_balance + period_delta, 2)
      )
      ORDER BY entry_date, document_no
    ),
    '[]'::jsonb
  )
  INTO v_lines
  FROM ordered;

  v_closing_balance := ROUND(
    v_initial_balance + COALESCE((
      SELECT SUM(our_debit - our_credit) FROM (
        SELECT ROUND(COALESCE(s.total_amount, 0), 2) AS our_debit, 0::numeric AS our_credit
        FROM public.sales s
        WHERE (
          s.partner_id = p_partner_id
          OR (v_customer_id IS NOT NULL AND s.customer_id = v_customer_id)
        )
          AND COALESCE(s.doc_date, (s.created_at AT TIME ZONE 'UTC')::date) BETWEEN p_start_date AND p_end_date
          AND COALESCE(s.status, '') NOT IN ('void', 'cancelled', 'deleted')
        UNION ALL
        SELECT 0::numeric, ROUND(COALESCE(p.total_amount, 0), 2)
        FROM public.purchases p
        WHERE (
          p.partner_id = p_partner_id
          OR (v_supplier_id IS NOT NULL AND p.supplier_id = v_supplier_id)
        )
          AND COALESCE(p.doc_date, (p.created_at AT TIME ZONE 'UTC')::date) BETWEEN p_start_date AND p_end_date
          AND COALESCE(p.status, '') NOT IN ('void', 'cancelled', 'deleted')
        UNION ALL
        SELECT
          CASE WHEN pay.payment_type = 'out' THEN ROUND(pay.amount, 2) ELSE 0 END,
          CASE WHEN pay.payment_type = 'in' THEN ROUND(pay.amount, 2) ELSE 0 END
        FROM public.payments pay
        WHERE pay.partner_id = p_partner_id
          AND (pay.payment_date AT TIME ZONE 'UTC')::date BETWEEN p_start_date AND p_end_date
      ) t
    ), 0),
    2
  );

  RETURN jsonb_build_object(
    'partner_id', p_partner_id,
    'partner_name', COALESCE(v_partner.full_name, v_partner.company_name, v_partner.name),
    'start_date', p_start_date,
    'end_date', p_end_date,
    'initial_balance', v_initial_balance,
    'closing_balance', v_closing_balance,
    'lines', v_lines
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.get_product_available_stock(p_product_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_composite BOOLEAN := false;
BEGIN
  SELECT COALESCE(is_composite, false)
  INTO v_is_composite
  FROM public.products
  WHERE id = p_product_id;

  IF NOT FOUND THEN
    RETURN 0;
  END IF;

  IF v_is_composite THEN
    RETURN public.get_composite_available_stock(p_product_id);
  END IF;

  RETURN public.get_batch_available_stock(p_product_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.gl_coa_for_payment_method(p_payment_method text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    WHEN lower(trim(COALESCE(p_payment_method, ''))) = 'bank' THEN '1100'
    ELSE '1000'
  END;
$function$;

CREATE OR REPLACE FUNCTION public.guard_journal_entry_period()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_date DATE;
BEGIN
  v_date := COALESCE(
    (CASE WHEN TG_OP = 'DELETE' THEN OLD.entry_date ELSE NEW.entry_date END),
    (CASE WHEN TG_OP = 'DELETE' THEN OLD.date::date ELSE NEW.date::date END),
    CURRENT_DATE
  );
  PERFORM public.assert_accounting_period_open(v_date);
  RETURN COALESCE(NEW, OLD);
END;
$function$;

CREATE OR REPLACE FUNCTION public.guard_profile_sensitive_updates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.id = auth.uid() AND NOT public.has_permission('can_manage_users') THEN
    IF NEW.role_id IS DISTINCT FROM OLD.role_id
       OR NEW.is_active IS DISTINCT FROM OLD.is_active
       OR NEW.employee_id IS DISTINCT FROM OLD.employee_id
       OR NEW.email IS DISTINCT FROM OLD.email
       OR NEW.id IS DISTINCT FROM OLD.id THEN
      RAISE EXCEPTION 'profile_update_forbidden'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  target_role_id UUID;
BEGIN
  SELECT id INTO target_role_id FROM roles
   WHERE name = COALESCE(NEW.raw_user_meta_data ->> 'role_name', 'User')
   LIMIT 1;

  IF target_role_id IS NULL THEN
    SELECT id INTO target_role_id FROM roles WHERE name = 'User' LIMIT 1;
  END IF;

  INSERT INTO profiles (id, email, full_name, role_id)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NULLIF(NEW.raw_user_meta_data ->> 'full_name', ''), split_part(NEW.email, '@', 1)),
    target_role_id
  )
  ON CONFLICT (id) DO UPDATE
    SET email = EXCLUDED.email,
        full_name = COALESCE(profiles.full_name, EXCLUDED.full_name),
        role_id = COALESCE(profiles.role_id, EXCLUDED.role_id);

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.handle_sales_posted_inventory()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_items JSONB := '[]'::jsonb;
  v_stock_demand JSONB := '{}'::jsonb;
  v_line RECORD;
BEGIN
  IF NEW.status IS DISTINCT FROM 'posted' THEN
    RETURN NEW;
  END IF;

  IF COALESCE(OLD.status, '') = 'posted' THEN
    RETURN NEW;
  END IF;

  IF OLD.inventory_deducted_at IS NOT NULL THEN
    RETURN NEW;
  END IF;

  SELECT COALESCE(
    jsonb_agg(
      jsonb_build_object(
        'product_id', si.product_id,
        'quantity', si.quantity,
        'warehouse_id', si.warehouse_id,
        'polywood_sale_mode', si.polywood_sale_mode,
        'polywood_length_m', si.polywood_length_m,
        'skip_stock', (si.polywood_sale_mode IS NOT NULL AND btrim(si.polywood_sale_mode) <> '')
      )
      ORDER BY si.id
    ),
    '[]'::jsonb
  )
  INTO v_items
  FROM public.sale_items si
  WHERE si.sale_id = NEW.id;

  IF jsonb_array_length(v_items) = 0 THEN
    RETURN NEW;
  END IF;

  v_stock_demand := public.build_and_validate_sale_stock_demand(v_items);
  PERFORM public.apply_sale_stock_decrement(v_stock_demand);

  FOR v_line IN
    SELECT
      si.id,
      si.product_id,
      si.quantity,
      si.warehouse_id,
      si.unit,
      p.name AS product_name
    FROM public.sale_items si
    LEFT JOIN public.products p ON p.id = si.product_id
    WHERE si.sale_id = NEW.id
      AND si.product_id IS NOT NULL
      AND COALESCE(si.quantity, 0) > 0
      AND (si.polywood_sale_mode IS NULL OR btrim(si.polywood_sale_mode) = '')
      AND NOT COALESCE(p.is_service, false)
  LOOP
    INSERT INTO public.stock_movements (
      product_id,
      warehouse_id,
      movement_type,
      quantity,
      unit,
      reference_type,
      reference_id,
      source_line_id,
      description,
      created_by
    )
    VALUES (
      v_line.product_id,
      v_line.warehouse_id,
      'out',
      v_line.quantity,
      COALESCE(v_line.unit, 'Ədəd'),
      'sale',
      NEW.id,
      v_line.id,
      format('Satış fakturası %s — %s', COALESCE(NEW.doc_no, NEW.id::text), COALESCE(v_line.product_name, '')),
      auth.uid()
    );
  END LOOP;

  NEW.inventory_deducted_at := NOW();
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.has_permission(perm text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (public.effective_user_permissions() ->> perm)::boolean,
    FALSE
  );
$function$;

CREATE OR REPLACE FUNCTION public.is_accounting_period_closed(p_date date)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.accounting_periods
    WHERE period_year = EXTRACT(YEAR FROM p_date)::int
      AND period_month = EXTRACT(MONTH FROM p_date)::int
      AND status = 'closed'
  );
$function$;

CREATE OR REPLACE FUNCTION public.is_active_user()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles
    WHERE id = auth.uid()
      AND COALESCE(is_active, TRUE)
  );
$function$;

CREATE OR REPLACE FUNCTION public.is_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.profiles
    WHERE id = auth.uid() AND role = 'admin'
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.is_invoice_cancelled(p_status text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT lower(trim(COALESCE(p_status, ''))) IN (
    'cancelled',
    'ləğv edildi',
    'legv edildi',
    'void',
    'voided'
  );
$function$;

CREATE OR REPLACE FUNCTION public.journal_entry_date(je public.journal_entries)
 RETURNS date
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT COALESCE((je.date AT TIME ZONE 'UTC')::date, je.entry_date);
$function$;

CREATE OR REPLACE FUNCTION public.log_erp_event(p_event_type text, p_source_table text, p_source_id uuid, p_payload jsonb, p_journal_entry_id uuid, p_idempotency_key text, p_result jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_event_id UUID;
BEGIN
  INSERT INTO public.erp_events (
    event_type,
    source_table,
    source_id,
    idempotency_key,
    payload,
    result,
    journal_entry_id
  )
  VALUES (
    p_event_type,
    p_source_table,
    p_source_id,
    NULLIF(trim(p_idempotency_key), ''),
    COALESCE(p_payload, '{}'::jsonb),
    p_result,
    p_journal_entry_id
  )
  RETURNING id INTO v_event_id;

  RETURN v_event_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.maybe_create_safety_stock_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.create_safety_stock_request(NEW.id);
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.merge_partners(p_source_partner_id uuid, p_target_partner_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_source partners%ROWTYPE;
  v_target partners%ROWTYPE;
  v_sales_moved INT := 0;
  v_purchases_moved INT := 0;
BEGIN
  IF p_source_partner_id IS NULL OR p_target_partner_id IS NULL THEN
    RAISE EXCEPTION 'partner_ids_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Hər iki tərəfdaş seçilməlidir';
  END IF;

  IF p_source_partner_id = p_target_partner_id THEN
    RAISE EXCEPTION 'same_partner'
      USING ERRCODE = '22023',
            MESSAGE = 'Eyni tərəfdaş seçilə bilməz';
  END IF;

  SELECT * INTO v_source FROM partners WHERE id = p_source_partner_id AND is_deleted = FALSE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'source_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Mənbə tərəfdaş tapılmadı';
  END IF;

  SELECT * INTO v_target FROM partners WHERE id = p_target_partner_id AND is_deleted = FALSE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'target_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Hədəf tərəfdaş tapılmadı';
  END IF;

  UPDATE sales
  SET partner_id = p_target_partner_id
  WHERE partner_id = p_source_partner_id;
  GET DIAGNOSTICS v_sales_moved = ROW_COUNT;

  IF v_source.customer_id IS NOT NULL THEN
    UPDATE sales
    SET partner_id = p_target_partner_id
    WHERE partner_id IS NULL
      AND customer_id = v_source.customer_id;
    v_sales_moved := v_sales_moved + ROW_COUNT;
  END IF;

  UPDATE purchases
  SET partner_id = p_target_partner_id
  WHERE partner_id = p_source_partner_id;
  GET DIAGNOSTICS v_purchases_moved = ROW_COUNT;

  IF v_source.supplier_id IS NOT NULL THEN
    UPDATE purchases
    SET partner_id = p_target_partner_id
    WHERE partner_id IS NULL
      AND supplier_id = v_source.supplier_id;
    v_purchases_moved := v_purchases_moved + ROW_COUNT;
  END IF;

  UPDATE partners
  SET
    is_customer = (v_target.is_customer OR v_source.is_customer),
    is_supplier = (v_target.is_supplier OR v_source.is_supplier),
    customer_id = COALESCE(v_target.customer_id, v_source.customer_id),
    supplier_id = COALESCE(v_target.supplier_id, v_source.supplier_id),
    email = COALESCE(NULLIF(trim(v_target.email), ''), NULLIF(trim(v_source.email), '')),
    bank_name = COALESCE(NULLIF(trim(v_target.bank_name), ''), NULLIF(trim(v_source.bank_name), '')),
    iban = COALESCE(NULLIF(trim(v_target.iban), ''), NULLIF(trim(v_source.iban), '')),
    credit_limit = GREATEST(COALESCE(v_target.credit_limit, 0), COALESCE(v_source.credit_limit, 0)),
    voen = COALESCE(NULLIF(trim(v_target.voen), ''), NULLIF(trim(v_source.voen), ''))
  WHERE id = p_target_partner_id;

  UPDATE partners
  SET
    is_deleted = TRUE,
    deleted_at = NOW()
  WHERE id = p_source_partner_id;

  RETURN jsonb_build_object(
    'target_partner_id', p_target_partner_id,
    'source_partner_id', p_source_partner_id,
    'sales_moved', v_sales_moved,
    'purchases_moved', v_purchases_moved
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.merge_stock_demand(p_demand jsonb, p_product_id uuid, p_quantity numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_is_composite BOOLEAN := false;
  v_bom RECORD;
  v_key TEXT;
  v_component_qty NUMERIC;
  v_result JSONB := COALESCE(p_demand, '{}'::jsonb);
BEGIN
  IF p_product_id IS NULL OR COALESCE(p_quantity, 0) <= 0 THEN
    RETURN v_result;
  END IF;

  SELECT COALESCE(is_composite, false)
  INTO v_is_composite
  FROM public.products
  WHERE id = p_product_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'product_not_found'
      USING ERRCODE = 'P0002', MESSAGE = format('Məhsul tapılmadı: %s', p_product_id);
  END IF;

  IF v_is_composite THEN
    IF NOT EXISTS (
      SELECT 1 FROM public.product_bom WHERE parent_product_id = p_product_id
    ) THEN
      RAISE EXCEPTION 'composite_bom_missing'
        USING ERRCODE = '22023',
              MESSAGE = format('Komplekt məhsul üçün BOM təyin edilməyib: %s', p_product_id);
    END IF;

    FOR v_bom IN
      SELECT component_product_id, quantity
      FROM public.product_bom
      WHERE parent_product_id = p_product_id
    LOOP
      v_key := v_bom.component_product_id::text;
      v_component_qty := COALESCE(p_quantity, 0) * COALESCE(v_bom.quantity, 1);
      v_result := jsonb_set(
        v_result,
        ARRAY[v_key],
        to_jsonb(COALESCE((v_result->>v_key)::numeric, 0) + v_component_qty),
        true
      );
    END LOOP;
  ELSE
    v_key := p_product_id::text;
    v_result := jsonb_set(
      v_result,
      ARRAY[v_key],
      to_jsonb(COALESCE((v_result->>v_key)::numeric, 0) + COALESCE(p_quantity, 0)),
      true
    );
  END IF;

  RETURN v_result;
END;
$function$;

CREATE OR REPLACE FUNCTION public.normalize_employee_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  NEW.status := CASE
    WHEN lower(btrim(COALESCE(NEW.status, ''))) IN ('', 'active', 'aktiv', 'активный', 'актив') THEN 'active'
    WHEN lower(btrim(NEW.status)) IN ('inactive', 'deaktiv', 'qeyri-aktiv', 'неактивный') THEN 'inactive'
    WHEN lower(btrim(NEW.status)) IN ('on_leave', 'məzuniyyətdə', 'mezuniyyetde', 'в отпуске') THEN 'on_leave'
    WHEN lower(btrim(NEW.status)) IN ('terminated', 'işdən çıxıb', 'isden cixib', 'уволен') THEN 'terminated'
    ELSE lower(btrim(NEW.status))
  END;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.post_cash_transaction(p_account_id uuid, p_type text, p_amount numeric, p_category text, p_notes text DEFAULT NULL::text, p_production_order_id uuid DEFAULT NULL::uuid, p_source_type text DEFAULT NULL::text, p_source_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_balance NUMERIC;
  v_tx_id UUID;
  v_type TEXT;
  v_category TEXT;
  v_journal_id UUID;
  v_counter_coa TEXT;
  v_memo TEXT;
BEGIN
  IF p_account_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Kassa/bank hesabı mütləqdir';
  END IF;

  IF p_amount IS NULL OR p_amount <= 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Məbləğ sıfırdan böyük olmalıdır';
  END IF;

  v_type := trim(COALESCE(p_type, ''));
  -- Legacy migrations stored Azerbaijani labels with broken encoding (MÉ™daxil / MÉ™xaric).
  IF v_type LIKE 'M%daxil' THEN
    v_type := 'Mədaxil';
  ELSIF v_type LIKE 'M%xaric' THEN
    v_type := 'Məxaric';
  END IF;

  IF v_type IS DISTINCT FROM 'Mədaxil' AND v_type IS DISTINCT FROM 'Məxaric' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Əməliyyat növü Mədaxil və ya Məxaric olmalıdır';
  END IF;

  v_category := COALESCE(NULLIF(trim(p_category), ''), 'Digər');
  v_memo := COALESCE(NULLIF(trim(p_notes), ''), v_category);

  IF public.resolve_coa_id('1100') IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0002',
      MESSAGE = 'Hesab planında 1100 (Kassa/Bank) tapılmadı — chart-of-accounts miqrasiyasını yoxlayın';
  END IF;

  SELECT balance INTO v_balance
  FROM public.accounts
  WHERE id = p_account_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Kassa/bank hesabı tapılmadı';
  END IF;

  IF v_type = 'Məxaric' AND COALESCE(v_balance, 0) + 0.0001 < p_amount THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Kassa/bank balansı kifayət etmir';
  END IF;

  INSERT INTO public.transactions (
    account_id, type, amount, category, notes, production_order_id, source_type, source_id
  )
  VALUES (
    p_account_id,
    v_type,
    p_amount,
    v_category,
    NULLIF(trim(p_notes), ''),
    p_production_order_id,
    NULLIF(trim(p_source_type), ''),
    p_source_id
  )
  RETURNING id INTO v_tx_id;

  IF v_type = 'Mədaxil' THEN
    UPDATE public.accounts
    SET balance = COALESCE(v_balance, 0) + p_amount
    WHERE id = p_account_id;

    v_counter_coa := public.coa_credit_for_cash_in(v_category);
    v_journal_id := public.post_journal_entry(
      jsonb_build_object(
        'source_type', 'cash_transaction',
        'source_id', v_tx_id,
        'idempotency_key', 'cash_tx:' || v_tx_id::text,
        'memo', v_memo,
        'lines', jsonb_build_array(
          jsonb_build_object(
            'coa_code', '1100',
            'debit', p_amount,
            'credit', 0,
            'account_id', p_account_id,
            'line_memo', v_memo
          ),
          jsonb_build_object(
            'coa_code', v_counter_coa,
            'debit', 0,
            'credit', p_amount,
            'line_memo', v_category
          )
        )
      )
    );
  ELSE
    UPDATE public.accounts
    SET balance = COALESCE(v_balance, 0) - p_amount
    WHERE id = p_account_id;

    v_counter_coa := public.coa_debit_for_cash_out(v_category);
    v_journal_id := public.post_journal_entry(
      jsonb_build_object(
        'source_type', 'cash_transaction',
        'source_id', v_tx_id,
        'idempotency_key', 'cash_tx:' || v_tx_id::text,
        'memo', v_memo,
        'lines', jsonb_build_array(
          jsonb_build_object(
            'coa_code', v_counter_coa,
            'debit', p_amount,
            'credit', 0,
            'line_memo', v_category
          ),
          jsonb_build_object(
            'coa_code', '1100',
            'debit', 0,
            'credit', p_amount,
            'account_id', p_account_id,
            'line_memo', v_memo
          )
        )
      )
    );
  END IF;

  UPDATE public.transactions
  SET journal_entry_id = v_journal_id
  WHERE id = v_tx_id;

  RETURN v_tx_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.post_cash_transaction(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
DECLARE
    v_tx_id UUID;
    v_account_id UUID;
    v_amount NUMERIC(14,2);
    v_type TEXT;
    v_journal_id UUID;
    v_coa_cash_id UUID;
    v_coa_counter_id UUID;
    v_category TEXT;
BEGIN
    v_account_id := (p_payload->>'account_id')::UUID;
    v_amount := (p_payload->>'amount')::NUMERIC;
    v_type := COALESCE(p_payload->>'type', 'Mədaxil');
    v_category := COALESCE(p_payload->>'category', 'Satış Ödənişi');

    IF v_account_id IS NULL THEN
        RAISE EXCEPTION 'Kassa və ya bank hesabı (account_id) seçilməlidir';
    END IF;

    IF v_amount IS NULL OR v_amount <= 0 THEN
        RAISE EXCEPTION 'Məbləğ düzgün daxil edilməyib';
    END IF;

    -- Insert into transactions table
    INSERT INTO public.transactions (
        type, category, amount, account_id, description, created_at
    ) VALUES (
        v_type,
        v_category,
        v_amount,
        v_account_id,
        COALESCE(p_payload->>'description', 'Ödəniş'),
        NOW()
    ) RETURNING id INTO v_tx_id;

    -- DIRECT UPDATE to Accounts Balance
    IF v_type = 'Mədaxil' THEN
        UPDATE public.accounts 
        SET balance = COALESCE(balance, 0) + v_amount 
        WHERE id = v_account_id;
    ELSIF v_type = 'Məxaric' THEN
        UPDATE public.accounts 
        SET balance = COALESCE(balance, 0) - v_amount 
        WHERE id = v_account_id;
    END IF;

    -- Get COA Accounts for Journal
    SELECT id INTO v_coa_cash_id FROM public.chart_of_accounts WHERE code = '1100' LIMIT 1;
    SELECT id INTO v_coa_counter_id FROM public.chart_of_accounts WHERE code = (CASE WHEN v_type = 'Mədaxil' THEN '1200' ELSE '2100' END) LIMIT 1;

    -- Post Journal Entry if COA exists
    IF v_coa_cash_id IS NOT NULL AND v_coa_counter_id IS NOT NULL THEN
        v_journal_id := public.post_journal_entry(jsonb_build_object(
            'source_type', 'cash_transaction',
            'source_id', v_tx_id,
            'memo', COALESCE(p_payload->>'description', 'Maliyyə əməliyyatı'),
            'lines', jsonb_build_array(
                jsonb_build_object('coa_id', CASE WHEN v_type = 'Mədaxil' THEN v_coa_cash_id ELSE v_coa_counter_id END, 'debit', v_amount, 'credit', 0, 'account_id', v_account_id),
                jsonb_build_object('coa_id', CASE WHEN v_type = 'Mədaxil' THEN v_coa_counter_id ELSE v_coa_cash_id END, 'debit', 0, 'credit', v_amount, 'account_id', v_account_id)
            )
        ));

        UPDATE public.transactions SET journal_entry_id = v_journal_id WHERE id = v_tx_id;
    END IF;

    RETURN v_tx_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.post_journal_entry(p_payload jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN public.create_journal_entry(p_payload);
END;
$function$;

CREATE OR REPLACE FUNCTION public.post_partner_payment_gl_journal(p_payment_id uuid, p_partner_id uuid, p_amount numeric, p_payment_type text, p_payment_method text, p_cash_account_id uuid, p_reference_note text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_coa_cash TEXT;
  v_memo TEXT;
BEGIN
  v_coa_cash := public.gl_coa_for_payment_method(p_payment_method);
  v_memo := COALESCE(NULLIF(trim(p_reference_note), ''), 'Tərəfdaş ödənişi');

  IF p_payment_type = 'in' THEN
    RETURN public.create_journal_entry(
      jsonb_build_object(
        'document_type', 'payment_receipt',
        'document_id', p_payment_id,
        'source_type', 'payment_receipt',
        'source_id', p_payment_id,
        'idempotency_key', 'partner_payment:' || p_payment_id::text,
        'description', v_memo,
        'memo', v_memo,
        'lines', jsonb_build_array(
          jsonb_build_object(
            'account_code', v_coa_cash,
            'debit', p_amount,
            'credit', 0,
            'cash_account_id', p_cash_account_id,
            'line_memo', v_memo
          ),
          jsonb_build_object(
            'account_code', '1200',
            'debit', 0,
            'credit', p_amount,
            'partner_type', 'partner',
            'partner_id', p_partner_id,
            'line_memo', 'Alacaq azaldılması — ' || v_memo
          )
        )
      )
    );
  END IF;

  RETURN public.create_journal_entry(
    jsonb_build_object(
      'document_type', 'payment_disbursement',
      'document_id', p_payment_id,
      'source_type', 'payment_disbursement',
      'source_id', p_payment_id,
      'idempotency_key', 'partner_payment:' || p_payment_id::text,
      'description', v_memo,
      'memo', v_memo,
      'lines', jsonb_build_array(
        jsonb_build_object(
          'account_code', '2100',
          'debit', p_amount,
          'credit', 0,
          'partner_type', 'partner',
          'partner_id', p_partner_id,
          'line_memo', 'Öhdəlik azaldılması — ' || v_memo
        ),
        jsonb_build_object(
          'account_code', v_coa_cash,
          'debit', 0,
          'credit', p_amount,
          'cash_account_id', p_cash_account_id,
          'line_memo', v_memo
        )
      )
    )
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.process_invoice_payment_event(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_idempotency TEXT;
  v_cached JSONB;
  v_document_type TEXT;
  v_document_id UUID;
  v_amount NUMERIC;
  v_account_id UUID;
  v_method TEXT;
  v_notes TEXT;
  v_payment_id TEXT;
  v_total_amount NUMERIC;
  v_paid_amount NUMERIC;
  v_remaining NUMERIC;
  v_debt_amount NUMERIC;
  v_new_paid NUMERIC;
  v_new_remaining NUMERIC;
  v_new_debt NUMERIC;
  v_customer_id UUID;
  v_supplier_id UUID;
  v_doc_label TEXT;
  v_payments JSONB;
  v_new_payment JSONB;
  v_status TEXT;
  v_tx_id UUID;
  v_journal_id UUID;
  v_event_id UUID;
  v_result JSONB;
  v_event_type TEXT;
  v_source_table TEXT;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödəniş event payload göndərilməyib';
  END IF;

  v_idempotency := NULLIF(trim(p_payload->>'idempotency_key'), '');
  IF v_idempotency IS NOT NULL THEN
    v_cached := public.find_erp_event_by_idempotency(v_idempotency);
    IF v_cached IS NOT NULL THEN
      RETURN v_cached->'result';
    END IF;
  END IF;

  v_document_type := lower(trim(COALESCE(p_payload->>'document_type', '')));
  v_document_id := NULLIF(p_payload->>'document_id', '')::uuid;
  v_amount := COALESCE(NULLIF(p_payload->>'amount', '')::numeric, 0);
  v_account_id := NULLIF(p_payload->>'account_id', '')::uuid;
  v_method := COALESCE(NULLIF(trim(p_payload->>'method'), ''), 'Ödəniş');
  v_notes := NULLIF(trim(p_payload->>'notes'), '');
  v_payment_id := COALESCE(NULLIF(trim(p_payload->>'payment_id'), ''), gen_random_uuid()::text);

  IF v_document_id IS NULL THEN
    RAISE EXCEPTION 'document_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Sənəd identifikatoru tələb olunur';
  END IF;

  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount'
      USING ERRCODE = '22023',
            MESSAGE = 'Məbləğ sıfırdan böyük olmalıdır';
  END IF;

  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'account_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Kassa/bank hesabı seçilməlidir';
  END IF;

  PERFORM id FROM accounts WHERE id = v_account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
  END IF;

  IF v_document_type = 'sale' THEN
    IF NOT (
      public.require_permission('can_edit_sales')
      OR public.require_permission('can_create_invoice')
      OR public.require_permission('can_manage_finance')
    ) THEN
      RAISE EXCEPTION 'forbidden'
        USING ERRCODE = '42501',
              MESSAGE = 'Satış ödənişi üçün icazəniz yoxdur';
    END IF;

    SELECT total_amount, paid_amount, remaining_balance, customer_id, doc_no, payments
    INTO v_total_amount, v_paid_amount, v_remaining, v_customer_id, v_doc_label, v_payments
    FROM sales
    WHERE id = v_document_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'sale_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Satış fakturası tapılmadı';
    END IF;

    v_total_amount := COALESCE(v_total_amount, 0);
    v_paid_amount := COALESCE(v_paid_amount, 0);
    v_remaining := GREATEST(COALESCE(v_remaining, v_total_amount - v_paid_amount), 0);

    IF v_amount > v_remaining + 0.0001 THEN
      RAISE EXCEPTION 'overpayment'
        USING ERRCODE = '22023',
              MESSAGE = format('Qalan borc: %s AZN', trim(to_char(v_remaining, 'FM999999990.00')));
    END IF;

    v_new_paid := v_paid_amount + v_amount;
    v_new_remaining := GREATEST(v_total_amount - v_new_paid, 0);

    v_new_payment := jsonb_build_object(
      'id', v_payment_id,
      'account_id', v_account_id::text,
      'method', v_method,
      'amount', v_amount
    );
    v_payments := COALESCE(v_payments, '[]'::jsonb) || jsonb_build_array(v_new_payment);

    UPDATE sales
    SET paid_amount = v_new_paid,
        remaining_balance = v_new_remaining,
        payments = v_payments
    WHERE id = v_document_id;

    v_tx_id := public.post_cash_transaction(
      v_account_id,
      'Mədaxil',
      v_amount,
      'Satış Ödənişi',
      COALESCE(v_notes, format('Satış fakturası %s — %s', COALESCE(v_doc_label, v_document_id::text), v_method)),
      NULL,
      'sale',
      v_document_id
    );

    SELECT journal_entry_id INTO v_journal_id
    FROM transactions
    WHERE id = v_tx_id;

    IF v_customer_id IS NOT NULL THEN
      PERFORM public.refresh_customer_ar_balance(v_customer_id);
    END IF;

    v_event_type := 'invoice_payment_sale';
    v_source_table := 'sales';

    v_result := jsonb_build_object(
      'success', true,
      'event_type', v_event_type,
      'document_type', 'sale',
      'document_id', v_document_id,
      'transaction_id', v_tx_id,
      'journal_entry_id', v_journal_id,
      'paid_amount', v_new_paid,
      'remaining_balance', v_new_remaining
    );
  ELSIF v_document_type = 'purchase' THEN
    IF NOT (
      public.require_permission('can_edit_purchases')
      OR public.require_permission('can_create_purchase')
      OR public.require_permission('can_manage_finance')
    ) THEN
      RAISE EXCEPTION 'forbidden'
        USING ERRCODE = '42501',
              MESSAGE = 'Alış ödənişi üçün icazəniz yoxdur';
    END IF;

    SELECT total_amount, paid_amount, debt_amount, supplier_id, invoice_number
    INTO v_total_amount, v_paid_amount, v_debt_amount, v_supplier_id, v_doc_label
    FROM purchases
    WHERE id = v_document_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'purchase_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Alış fakturası tapılmadı';
    END IF;

    v_total_amount := COALESCE(v_total_amount, 0);
    v_paid_amount := COALESCE(v_paid_amount, 0);
    v_debt_amount := GREATEST(COALESCE(v_debt_amount, v_total_amount - v_paid_amount), 0);

    IF v_amount > v_debt_amount + 0.0001 THEN
      RAISE EXCEPTION 'overpayment'
        USING ERRCODE = '22023',
              MESSAGE = format('Qalan borc: %s AZN', trim(to_char(v_debt_amount, 'FM999999990.00')));
    END IF;

    v_new_paid := v_paid_amount + v_amount;
    v_new_debt := GREATEST(v_total_amount - v_new_paid, 0);
    v_status := CASE WHEN v_new_debt > 0.0001 THEN 'Borclu' ELSE 'Ödənilib' END;

    UPDATE purchases
    SET paid_amount = v_new_paid,
        debt_amount = v_new_debt,
        status = v_status
    WHERE id = v_document_id;

    v_tx_id := public.post_cash_transaction(
      v_account_id,
      'Məxaric',
      v_amount,
      'Alış Ödənişi',
      COALESCE(v_notes, format('Alış fakturası %s — %s', COALESCE(v_doc_label, v_document_id::text), v_method)),
      NULL,
      'purchase',
      v_document_id
    );

    SELECT journal_entry_id INTO v_journal_id
    FROM transactions
    WHERE id = v_tx_id;

    IF v_supplier_id IS NOT NULL THEN
      PERFORM public.refresh_supplier_ap_balance(v_supplier_id);
    END IF;

    v_event_type := 'invoice_payment_purchase';
    v_source_table := 'purchases';

    v_result := jsonb_build_object(
      'success', true,
      'event_type', v_event_type,
      'document_type', 'purchase',
      'document_id', v_document_id,
      'transaction_id', v_tx_id,
      'journal_entry_id', v_journal_id,
      'paid_amount', v_new_paid,
      'debt_amount', v_new_debt,
      'status', v_status
    );
  ELSE
    RAISE EXCEPTION 'invalid_document_type'
      USING ERRCODE = '22023',
            MESSAGE = 'document_type «sale» və ya «purchase» olmalıdır';
  END IF;

  v_event_id := public.log_erp_event(
    v_event_type,
    v_source_table,
    v_document_id,
    p_payload,
    v_journal_id,
    v_idempotency,
    v_result
  );

  RETURN v_result || jsonb_build_object('event_id', v_event_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.process_mixed_dimensional_sale(p_product_id uuid, p_warehouse_id uuid, p_item_type text, p_sale_mode text DEFAULT NULL::text, p_amount numeric DEFAULT 0, p_piece_count integer DEFAULT 1, p_sale_item_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_product RECORD;
  v_base_length NUMERIC;
  v_remaining NUMERIC;
  v_target INTEGER;
  v_piece RECORD;
  v_new_piece_id UUID;
  v_leftover NUMERIC;
  v_steps JSONB := '[]'::jsonb;
  v_scrap JSONB := '[]'::jsonb;
  v_i INTEGER;
BEGIN
  IF p_item_type IS NULL THEN
    RAISE EXCEPTION 'item_type is required';
  END IF;

  IF p_item_type = 'service' THEN
    RETURN jsonb_build_object('ok', true, 'item_type', 'service', 'steps', v_steps);
  END IF;

  IF p_product_id IS NULL THEN
    RAISE EXCEPTION 'product_id is required';
  END IF;

  SELECT * INTO v_product FROM products WHERE id = p_product_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Product % not found', p_product_id;
  END IF;

  IF p_item_type = 'accessory' THEN
    IF p_amount IS NULL OR p_amount <= 0 THEN
      RAISE EXCEPTION 'Accessory quantity must be positive';
    END IF;
    IF COALESCE(v_product.stock, 0) < p_amount THEN
      RAISE EXCEPTION 'Insufficient stock for "%": have %, need %', v_product.name, v_product.stock, p_amount;
    END IF;
    UPDATE products SET stock = stock - p_amount WHERE id = p_product_id;
    RETURN jsonb_build_object('ok', true, 'item_type', 'accessory', 'deducted', p_amount);
  END IF;

  IF p_item_type <> 'dimensional' THEN
    RAISE EXCEPTION 'Unknown item_type %', p_item_type;
  END IF;

  IF p_warehouse_id IS NULL THEN
    RAISE EXCEPTION 'warehouse_id is required for dimensional items';
  END IF;

  v_base_length := COALESCE(v_product.base_length, v_product.full_sheet_length_m, 4);

  IF p_sale_mode = 'full_sheet' THEN
    v_target := ROUND(COALESCE(p_amount, 0))::INTEGER;
    IF v_target <= 0 THEN
      RAISE EXCEPTION 'Full sheet quantity must be positive';
    END IF;

    FOR v_piece IN
      SELECT * FROM polywood_pieces
      WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id
        AND status = 'available' AND piece_type = 'full'
        AND ABS(length_m - v_base_length) < 0.001
      ORDER BY created_at ASC
      LIMIT v_target
      FOR UPDATE
    LOOP
      UPDATE polywood_pieces
      SET status = 'sold', sale_item_id = p_sale_item_id, updated_at = NOW()
      WHERE id = v_piece.id;
      v_steps := v_steps || jsonb_build_object(
        'piece_id', v_piece.id, 'action', 'consume', 'used_length', v_base_length
      );
      v_target := v_target - 1;
    END LOOP;

    IF v_target > 0 THEN
      RAISE EXCEPTION 'Insufficient full sheets for "%": missing % sheet(s)', v_product.name, v_target;
    END IF;

  ELSIF p_sale_mode IN ('meter', 'linear_m') THEN
    IF p_amount IS NULL OR p_amount <= 0 THEN
      RAISE EXCEPTION 'Length must be positive';
    END IF;

    FOR v_i IN 1..GREATEST(COALESCE(p_piece_count, 1), 1) LOOP
      v_remaining := ROUND(p_amount, 3);

      -- 1) Exact-length piece first (prefer an off-cut over a full sheet).
      SELECT * INTO v_piece FROM polywood_pieces
      WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id
        AND status = 'available' AND ABS(length_m - v_remaining) < 0.001
      ORDER BY (piece_type = 'cut') DESC, created_at ASC
      LIMIT 1
      FOR UPDATE;

      IF FOUND THEN
        UPDATE polywood_pieces
        SET status = 'sold', sale_item_id = p_sale_item_id, updated_at = NOW()
        WHERE id = v_piece.id;
        v_steps := v_steps || jsonb_build_object(
          'piece_id', v_piece.id, 'action', 'consume', 'used_length', v_remaining
        );
        CONTINUE;
      END IF;

      -- 2) Smallest larger off-cut, else smallest larger full sheet.
      SELECT * INTO v_piece FROM polywood_pieces
      WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id
        AND status = 'available' AND piece_type = 'cut'
        AND length_m > v_remaining + 0.001
      ORDER BY length_m ASC
      LIMIT 1
      FOR UPDATE;

      IF NOT FOUND THEN
        SELECT * INTO v_piece FROM polywood_pieces
        WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id
          AND status = 'available' AND piece_type = 'full'
          AND length_m > v_remaining + 0.001
        ORDER BY length_m ASC
        LIMIT 1
        FOR UPDATE;
      END IF;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'Insufficient material for "%" (need %m more)', v_product.name, v_remaining;
      END IF;

      v_leftover := ROUND(v_piece.length_m - v_remaining, 3);

      IF v_piece.piece_type = 'full' THEN
        -- Full sheet is consumed as raw material; remnant becomes a new off-cut.
        UPDATE polywood_pieces
        SET status = 'consumed', sale_item_id = p_sale_item_id, updated_at = NOW()
        WHERE id = v_piece.id;
        v_steps := v_steps || jsonb_build_object(
          'piece_id', v_piece.id, 'action', 'split_full',
          'used_length', v_remaining, 'scrap_length', v_leftover
        );

        IF v_leftover > 0.001 THEN
          INSERT INTO polywood_pieces (product_id, warehouse_id, length_m, piece_type, status, notes)
          VALUES (
            p_product_id, p_warehouse_id, v_leftover, 'cut', 'available',
            'Auto remnant from sale item ' || COALESCE(p_sale_item_id::text, 'n/a')
          )
          RETURNING id INTO v_new_piece_id;
          v_scrap := v_scrap || jsonb_build_object('piece_id', v_new_piece_id, 'length_m', v_leftover);
        END IF;
      ELSE
        -- Off-cut: shrink the existing piece in place, no new row needed.
        UPDATE polywood_pieces
        SET length_m = v_leftover, updated_at = NOW()
        WHERE id = v_piece.id;
        v_steps := v_steps || jsonb_build_object(
          'piece_id', v_piece.id, 'action', 'partial',
          'used_length', v_remaining, 'remaining_on_piece', v_leftover
        );
      END IF;
    END LOOP;
  ELSE
    RAISE EXCEPTION 'Unknown sale_mode % for dimensional item', p_sale_mode;
  END IF;

  IF p_sale_item_id IS NOT NULL THEN
    UPDATE sale_items
    SET polywood_cut_details = jsonb_build_object('steps', v_steps, 'scrap_created', v_scrap)
    WHERE id = p_sale_item_id;
  END IF;

  -- Keep products.stock in sync as "total metres currently in stock" for dimensional items.
  UPDATE products
  SET stock = (
    SELECT COALESCE(SUM(length_m), 0)
    FROM polywood_pieces
    WHERE product_id = p_product_id AND warehouse_id = p_warehouse_id AND status = 'available'
  )
  WHERE id = p_product_id;

  RETURN jsonb_build_object('ok', true, 'item_type', 'dimensional', 'steps', v_steps, 'scrap_created', v_scrap);
END;
$function$;

CREATE OR REPLACE FUNCTION public.purchases_default_posted_when_blank()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status IS NULL OR btrim(NEW.status) = '' THEN
    NEW.status := 'posted';
  END IF;
  IF NEW.payments IS NULL THEN
    NEW.payments := '[]'::jsonb;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.purge_expired_audit_logs()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cfg JSONB;
  v_days INT;
  v_count INT := 0;
BEGIN
  SELECT value INTO v_cfg
    FROM public.system_settings
   WHERE key = 'audit_config';

  v_days := COALESCE((v_cfg ->> 'log_retention_days')::int, 0);
  IF v_days IS NULL OR v_days <= 0 THEN
    RETURN 0;
  END IF;

  DELETE FROM public.audit_alerts
   WHERE created_at < NOW() - make_interval(days => v_days);

  DELETE FROM public.audit_logs
   WHERE created_at < NOW() - make_interval(days => v_days);
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reconcile_account_balance_atomic(p_account_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row RECORD;
  v_ledger NUMERIC;
  v_previous NUMERIC;
  v_fixed INT := 0;
  v_results JSONB := '[]'::jsonb;
BEGIN
  IF NOT (
    public.require_permission('can_manage_finance')
    OR public.require_permission('can_manage_settings')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Balans uyğunlaşdırması üçün icazəniz yoxdur';
  END IF;

  FOR v_row IN
    SELECT id, balance, name, code
    FROM accounts
    WHERE p_account_id IS NULL OR id = p_account_id
    ORDER BY name
  LOOP
    SELECT COALESCE(SUM(
      CASE
        WHEN type = 'Mədaxil' THEN amount
        WHEN type = 'Məxaric' THEN -amount
        ELSE 0
      END
    ), 0)
    INTO v_ledger
    FROM transactions
    WHERE account_id = v_row.id;

    v_previous := COALESCE(v_row.balance, 0);

    UPDATE accounts
    SET balance = COALESCE(v_ledger, 0)
    WHERE id = v_row.id;

    IF abs(v_previous - COALESCE(v_ledger, 0)) > 0.0001 THEN
      v_fixed := v_fixed + 1;
    END IF;

    v_results := v_results || jsonb_build_array(
      jsonb_build_object(
        'account_id', v_row.id,
        'account_name', v_row.name,
        'account_code', v_row.code,
        'previous_balance', v_previous,
        'ledger_balance', COALESCE(v_ledger, 0),
        'adjusted', abs(v_previous - COALESCE(v_ledger, 0)) > 0.0001
      )
    );
  END LOOP;

  IF p_account_id IS NOT NULL AND v_fixed = 0 AND jsonb_array_length(v_results) = 0 THEN
    RAISE EXCEPTION 'account_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Hesab tapılmadı';
  END IF;

  RETURN jsonb_build_object(
    'accounts_checked', jsonb_array_length(v_results),
    'accounts_adjusted', v_fixed,
    'results', v_results
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.reconcile_accounts_for_transactions(p_account_ids uuid[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account_id UUID;
BEGIN
  IF p_account_ids IS NULL THEN
    RETURN;
  END IF;

  FOREACH v_account_id IN ARRAY p_account_ids
  LOOP
    IF v_account_id IS NOT NULL THEN
      PERFORM public.reconcile_account_balance_atomic(v_account_id);
    END IF;
  END LOOP;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reconcile_customer_ar_balances(p_customer_id uuid DEFAULT NULL::uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_customer RECORD;
  v_fixed INT := 0;
  v_results JSONB := '[]'::jsonb;
  v_before NUMERIC;
  v_after NUMERIC;
BEGIN
  IF NOT (
    public.require_permission('can_manage_finance')
    OR public.require_permission('can_edit_sales')
    OR public.require_permission('can_manage_settings')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'Müştəri borc uyğunlaşdırması üçün icazəniz yoxdur';
  END IF;

  FOR v_customer IN
    SELECT id, balance, full_name, name, company_name, code
    FROM customers
    WHERE p_customer_id IS NULL OR id = p_customer_id
    ORDER BY full_name NULLS LAST, name NULLS LAST
  LOOP
    v_before := COALESCE(v_customer.balance, 0);
    v_after := public.refresh_customer_ar_balance(v_customer.id);

    IF abs(v_before - COALESCE(v_after, 0)) > 0.01 THEN
      v_fixed := v_fixed + 1;
    END IF;

    v_results := v_results || jsonb_build_array(
      jsonb_build_object(
        'customer_id', v_customer.id,
        'customer_name', COALESCE(NULLIF(trim(v_customer.full_name), ''), NULLIF(trim(v_customer.name), ''), NULLIF(trim(v_customer.company_name), ''), v_customer.code, v_customer.id::text),
        'previous_balance', v_before,
        'ledger_balance', COALESCE(v_after, 0),
        'adjusted', abs(v_before - COALESCE(v_after, 0)) > 0.01
      )
    );
  END LOOP;

  IF p_customer_id IS NOT NULL AND jsonb_array_length(v_results) = 0 THEN
    RAISE EXCEPTION 'customer_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Müştəri tapılmadı';
  END IF;

  RETURN jsonb_build_object(
    'customers_checked', jsonb_array_length(v_results),
    'customers_adjusted', v_fixed,
    'results', v_results
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.record_payment_atomic(p_payload jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_document_type TEXT;
  v_document_id UUID;
  v_amount NUMERIC;
  v_account_id UUID;
  v_method TEXT;
  v_notes TEXT;
  v_payment_id TEXT;
  v_total_amount NUMERIC;
  v_paid_amount NUMERIC;
  v_remaining NUMERIC;
  v_debt_amount NUMERIC;
  v_new_paid NUMERIC;
  v_new_remaining NUMERIC;
  v_new_debt NUMERIC;
  v_customer_id UUID;
  v_supplier_id UUID;
  v_doc_label TEXT;
  v_account_balance NUMERIC;
  v_party_balance NUMERIC;
  v_payments JSONB;
  v_new_payment JSONB;
  v_status TEXT;
BEGIN
  IF p_payload IS NULL THEN
    RAISE EXCEPTION 'invalid_payload'
      USING ERRCODE = '22023',
            MESSAGE = 'Ödəniş məlumatları göndərilməyib';
  END IF;

  v_document_type := lower(trim(COALESCE(p_payload->>'document_type', '')));
  v_document_id := NULLIF(p_payload->>'document_id', '')::uuid;
  v_amount := COALESCE(NULLIF(p_payload->>'amount', '')::numeric, 0);
  v_account_id := NULLIF(p_payload->>'account_id', '')::uuid;
  v_method := COALESCE(NULLIF(trim(p_payload->>'method'), ''), 'Ödəniş');
  v_notes := NULLIF(trim(p_payload->>'notes'), '');
  v_payment_id := COALESCE(NULLIF(trim(p_payload->>'payment_id'), ''), gen_random_uuid()::text);

  IF v_document_id IS NULL THEN
    RAISE EXCEPTION 'document_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Sənəd identifikatoru tələb olunur';
  END IF;

  IF v_amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount'
      USING ERRCODE = '22023',
            MESSAGE = 'Məbləğ sıfırdan böyük olmalıdır';
  END IF;

  IF v_account_id IS NULL THEN
    RAISE EXCEPTION 'account_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Kassa/bank hesabı seçilməlidir';
  END IF;

  PERFORM id FROM accounts WHERE id = v_account_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Seçilmiş kassa/bank hesabı tapılmadı';
  END IF;

  IF v_document_type = 'sale' THEN
    IF NOT public.require_permission('can_edit_sales') THEN
      RAISE EXCEPTION 'forbidden'
        USING ERRCODE = '42501',
              MESSAGE = 'Satış ödənişi üçün icazəniz yoxdur';
    END IF;

    SELECT
      total_amount,
      paid_amount,
      remaining_balance,
      customer_id,
      doc_no,
      payments
    INTO
      v_total_amount,
      v_paid_amount,
      v_remaining,
      v_customer_id,
      v_doc_label,
      v_payments
    FROM sales
    WHERE id = v_document_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'sale_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Satış fakturası tapılmadı';
    END IF;

    v_total_amount := COALESCE(v_total_amount, 0);
    v_paid_amount := COALESCE(v_paid_amount, 0);
    v_remaining := GREATEST(
      COALESCE(v_remaining, v_total_amount - v_paid_amount),
      0
    );

    IF v_amount > v_remaining + 0.0001 THEN
      RAISE EXCEPTION 'overpayment'
        USING ERRCODE = '22023',
              MESSAGE = format('Qalan borc: %s AZN', trim(to_char(v_remaining, 'FM999999990.00')));
    END IF;

    v_new_paid := v_paid_amount + v_amount;
    v_new_remaining := GREATEST(v_total_amount - v_new_paid, 0);

    v_new_payment := jsonb_build_object(
      'id', v_payment_id,
      'account_id', v_account_id::text,
      'method', v_method,
      'amount', v_amount
    );
    v_payments := COALESCE(v_payments, '[]'::jsonb) || jsonb_build_array(v_new_payment);

    UPDATE sales
    SET
      paid_amount = v_new_paid,
      remaining_balance = v_new_remaining,
      payments = v_payments
    WHERE id = v_document_id;

    SELECT balance INTO v_account_balance
    FROM accounts
    WHERE id = v_account_id
    FOR UPDATE;

    INSERT INTO transactions (account_id, type, amount, category, notes)
    VALUES (
      v_account_id,
      'Mədaxil',
      v_amount,
      'Satış Ödənişi',
      COALESCE(
        v_notes,
        format('Satış fakturası %s — %s', COALESCE(v_doc_label, v_document_id::text), v_method)
      )
    );

    UPDATE accounts
    SET balance = COALESCE(v_account_balance, 0) + v_amount
    WHERE id = v_account_id;

    IF v_customer_id IS NOT NULL THEN
      SELECT balance INTO v_party_balance
      FROM customers
      WHERE id = v_customer_id
      FOR UPDATE;

      UPDATE customers
      SET balance = GREATEST(COALESCE(v_party_balance, 0) - v_amount, 0)
      WHERE id = v_customer_id;
    END IF;

    RETURN jsonb_build_object(
      'document_type', 'sale',
      'document_id', v_document_id,
      'paid_amount', v_new_paid,
      'remaining_balance', v_new_remaining
    );
  END IF;

  IF v_document_type = 'purchase' THEN
    IF NOT public.require_permission('can_edit_purchases') THEN
      RAISE EXCEPTION 'forbidden'
        USING ERRCODE = '42501',
              MESSAGE = 'Alış ödənişi üçün icazəniz yoxdur';
    END IF;

    SELECT
      total_amount,
      paid_amount,
      debt_amount,
      supplier_id,
      invoice_number
    INTO
      v_total_amount,
      v_paid_amount,
      v_debt_amount,
      v_supplier_id,
      v_doc_label
    FROM purchases
    WHERE id = v_document_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'purchase_not_found'
        USING ERRCODE = 'P0002',
              MESSAGE = 'Alış fakturası tapılmadı';
    END IF;

    v_total_amount := COALESCE(v_total_amount, 0);
    v_paid_amount := COALESCE(v_paid_amount, 0);
    v_debt_amount := GREATEST(COALESCE(v_debt_amount, v_total_amount - v_paid_amount), 0);

    IF v_amount > v_debt_amount + 0.0001 THEN
      RAISE EXCEPTION 'overpayment'
        USING ERRCODE = '22023',
              MESSAGE = format('Qalan borc: %s AZN', trim(to_char(v_debt_amount, 'FM999999990.00')));
    END IF;

    v_new_paid := v_paid_amount + v_amount;
    v_new_debt := GREATEST(v_total_amount - v_new_paid, 0);
    v_status := CASE WHEN v_new_debt > 0.0001 THEN 'Borclu' ELSE 'Ödənilib' END;

    UPDATE purchases
    SET
      paid_amount = v_new_paid,
      debt_amount = v_new_debt,
      status = v_status
    WHERE id = v_document_id;

    SELECT balance INTO v_account_balance
    FROM accounts
    WHERE id = v_account_id
    FOR UPDATE;

    INSERT INTO transactions (account_id, type, amount, category, notes)
    VALUES (
      v_account_id,
      'Məxaric',
      v_amount,
      'Alış Ödənişi',
      COALESCE(
        v_notes,
        format('Alış fakturası %s — %s', COALESCE(v_doc_label, v_document_id::text), v_method)
      )
    );

    UPDATE accounts
    SET balance = COALESCE(v_account_balance, 0) - v_amount
    WHERE id = v_account_id;

    IF v_supplier_id IS NOT NULL THEN
      SELECT balance INTO v_party_balance
      FROM suppliers
      WHERE id = v_supplier_id
      FOR UPDATE;

      UPDATE suppliers
      SET balance = GREATEST(COALESCE(v_party_balance, 0) - v_amount, 0)
      WHERE id = v_supplier_id;
    END IF;

    RETURN jsonb_build_object(
      'document_type', 'purchase',
      'document_id', v_document_id,
      'paid_amount', v_new_paid,
      'debt_amount', v_new_debt,
      'status', v_status
    );
  END IF;

  RAISE EXCEPTION 'invalid_document_type'
    USING ERRCODE = '22023',
          MESSAGE = 'document_type «sale» və ya «purchase» olmalıdır';
END;
$function$;

CREATE OR REPLACE FUNCTION public.refresh_customer_ar_balance(p_customer_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_open_ar NUMERIC;
BEGIN
  IF p_customer_id IS NULL THEN
    RETURN 0;
  END IF;

  v_open_ar := public.compute_customer_open_ar(p_customer_id);

  UPDATE customers
  SET balance = COALESCE(v_open_ar, 0)
  WHERE id = p_customer_id;

  RETURN COALESCE(v_open_ar, 0);
END;
$function$;

CREATE OR REPLACE FUNCTION public.refresh_partner_linked_balances(p_partner_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_partner public.partners%ROWTYPE;
BEGIN
  SELECT * INTO v_partner
  FROM public.partners
  WHERE id = p_partner_id AND is_deleted = FALSE;

  IF NOT FOUND THEN
    RETURN;
  END IF;

  IF v_partner.customer_id IS NOT NULL THEN
    PERFORM public.refresh_customer_ar_balance(v_partner.customer_id);
  END IF;

  IF v_partner.supplier_id IS NOT NULL THEN
    PERFORM public.refresh_supplier_ap_balance(v_partner.supplier_id);
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.refresh_supplier_ap_balance(p_supplier_id uuid)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_open_ap NUMERIC;
BEGIN
  IF p_supplier_id IS NULL THEN
    RETURN 0;
  END IF;

  v_open_ap := public.compute_supplier_open_ap(p_supplier_id);

  UPDATE public.suppliers
  SET balance = COALESCE(v_open_ap, 0)
  WHERE id = p_supplier_id;

  RETURN COALESCE(v_open_ap, 0);
END;
$function$;

CREATE OR REPLACE FUNCTION public.require_permission(perm text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  RETURN public.is_active_user()
     AND public.has_permission(perm);
END;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_coa_id(p_code text)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT id
  FROM public.chart_of_accounts
  WHERE code = trim(p_code)
    AND is_active = true
  LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_default_cash_account_id(p_payment_method text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_account_id UUID;
  v_type TEXT := CASE
    WHEN lower(trim(COALESCE(p_payment_method, ''))) = 'bank' THEN 'Bank'
    ELSE 'Kassa'
  END;
BEGIN
  SELECT id INTO v_account_id
  FROM public.accounts
  WHERE type = v_type
  ORDER BY name
  LIMIT 1;

  IF v_account_id IS NULL THEN
    SELECT id INTO v_account_id
    FROM public.accounts
    ORDER BY name
    LIMIT 1;
  END IF;

  RETURN v_account_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_financial_category_id(p_name text, p_type text DEFAULT 'EXPENSE'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id UUID;
  v_name TEXT := COALESCE(NULLIF(trim(p_name), ''), 'Digər');
  v_type TEXT := upper(COALESCE(NULLIF(trim(p_type), ''), 'EXPENSE'));
BEGIN
  SELECT id INTO v_id
  FROM financial_categories
  WHERE lower(name) = lower(v_name) AND type = v_type AND is_active = true
  LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN v_id;
  END IF;

  INSERT INTO financial_categories (name, type, is_active)
  VALUES (v_name, v_type, true)
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    SELECT id INTO v_id
    FROM financial_categories
    WHERE lower(name) = lower(v_name) AND type = v_type
    LIMIT 1;
  END IF;

  RETURN v_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_gl_account_id(p_code text)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT id
  FROM public.chart_of_accounts
  WHERE code = trim(p_code)
    AND is_active = true
  LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.resolve_unified_partner_id(p_customer_id uuid DEFAULT NULL::uuid, p_supplier_id uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  SELECT p.id
  FROM public.partners p
  WHERE p.is_deleted = FALSE
    AND (
      (p_customer_id IS NOT NULL AND p.customer_id = p_customer_id)
      OR (p_supplier_id IS NOT NULL AND p.supplier_id = p_supplier_id)
    )
  ORDER BY p.created_at NULLS LAST
  LIMIT 1;
$function$;

CREATE OR REPLACE FUNCTION public.reverse_document_cash_transactions(p_source_type text, p_source_id uuid, p_doc_label text, p_reason text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r          RECORD;
  v_balance  NUMERIC;
  v_is_in    BOOLEAN;
  v_journal  UUID;
  v_count    INTEGER := 0;
BEGIN
  FOR r IN
    SELECT t.*
    FROM public.transactions t
    WHERE (
        (t.source_type = p_source_type AND t.source_id = p_source_id)
        -- Rows written before source linkage existed carry the number in notes.
        OR (t.source_type IS NULL AND t.source_id IS NULL
            AND NULLIF(trim(p_doc_label), '') IS NOT NULL
            AND t.notes ILIKE '%' || trim(p_doc_label) || '%')
      )
      AND COALESCE(t.reference_type, '') <> 'storno'
      AND NOT EXISTS (
        SELECT 1 FROM public.transactions s
        WHERE s.reference_type = 'storno' AND s.reference_id = t.id
      )
    ORDER BY t.created_at, t.id
    FOR UPDATE OF t
  LOOP
    IF r.account_id IS NULL OR COALESCE(r.amount, 0) <= 0 THEN
      CONTINUE;
    END IF;

    v_is_in := r.type LIKE 'M%daxil';

    SELECT balance INTO v_balance
    FROM public.accounts
    WHERE id = r.account_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = 'P0002',
        MESSAGE = format('%s: ödənişin kassa/bank hesabı tapılmadı', p_doc_label);
    END IF;

    -- Money received is paid back out of the same kassa/bank.
    IF v_is_in AND COALESCE(v_balance, 0) + 0.0001 < r.amount THEN
      RAISE EXCEPTION USING ERRCODE = '22023',
        MESSAGE = format(
          '%s: geri qaytarmaq üçün kassa/bank balansı kifayət etmir (lazım: %s, mövcud: %s)',
          p_doc_label,
          trim(to_char(r.amount, 'FM999999990.00')),
          trim(to_char(COALESCE(v_balance, 0), 'FM999999990.00'))
        );
    END IF;

    UPDATE public.accounts
    SET balance = COALESCE(balance, 0) + CASE WHEN v_is_in THEN -r.amount ELSE r.amount END
    WHERE id = r.account_id;

    v_journal := NULL;
    IF r.journal_entry_id IS NOT NULL THEN
      v_journal := public.reverse_journal_entry(r.journal_entry_id, p_reason);
    END IF;

    INSERT INTO public.transactions (
      account_id, type, amount, category, notes,
      source_type, source_id, reference_type, reference_id, journal_entry_id
    )
    VALUES (
      r.account_id,
      CASE WHEN v_is_in THEN 'Məxaric' ELSE 'Mədaxil' END,
      r.amount,
      COALESCE(r.category, 'Digər') || ' (storno)',
      format('STORNO: %s — %s', COALESCE(r.notes, p_doc_label), p_reason),
      r.source_type,
      r.source_id,
      'storno',
      r.id,
      v_journal
    );

    v_count := v_count + 1;
  END LOOP;

  RETURN v_count;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reverse_document_journals(p_document_id uuid, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r     RECORD;
  v_cnt INTEGER := 0;
BEGIN
  FOR r IN
    SELECT id FROM public.journal_entries
    WHERE COALESCE(document_id, source_id) = p_document_id
      AND reversal_of IS NULL
      AND reversed_by IS NULL
  LOOP
    PERFORM public.reverse_journal_entry(r.id, p_reason);
    v_cnt := v_cnt + 1;
  END LOOP;
  RETURN v_cnt;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reverse_journal_entry(p_entry_id uuid, p_reason text DEFAULT NULL::text, p_date date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_src    RECORD;
  v_new_id UUID;
  v_date   DATE;
BEGIN
  SELECT * INTO v_src FROM public.journal_entries WHERE id = p_entry_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'entry_not_found'
      USING ERRCODE = 'P0002', MESSAGE = 'Müxabirləşmə tapılmadı';
  END IF;

  IF v_src.reversed_by IS NOT NULL THEN
    RETURN v_src.reversed_by;           -- idempotent
  END IF;

  IF v_src.reversal_of IS NOT NULL THEN
    RAISE EXCEPTION 'already_a_reversal'
      USING ERRCODE = '22023', MESSAGE = 'Storno sənədi yenidən stornolana bilməz';
  END IF;

  -- Reverse into the original period when it is open, otherwise today.
  v_date := COALESCE(p_date, v_src.entry_date, CURRENT_DATE);
  IF public.is_accounting_period_closed(v_date) THEN
    v_date := CURRENT_DATE;
  END IF;

  INSERT INTO public.journal_entries (
    entry_no, entry_date, date, source_type, source_id,
    document_type, document_id, memo, description,
    idempotency_key, reversal_of, reversal_reason, created_by
  )
  VALUES (
    'STORNO-' || v_src.entry_no,
    v_date,
    v_date::timestamptz,
    v_src.source_type,
    v_src.source_id,
    v_src.document_type,
    v_src.document_id,
    'STORNO: ' || COALESCE(v_src.memo, v_src.entry_no),
    COALESCE(p_reason, 'Storno: ' || COALESCE(v_src.description, v_src.entry_no)),
    'storno:' || p_entry_id::text,
    p_entry_id,
    p_reason,
    auth.uid()
  )
  RETURNING id INTO v_new_id;

  -- Swap debit and credit, keep account and analytics.
  INSERT INTO public.journal_entry_lines (
    journal_entry_id, coa_id, debit, credit, partner_type, partner_id, account_id, line_memo
  )
  SELECT v_new_id, l.coa_id, l.credit, l.debit, l.partner_type, l.partner_id, l.account_id,
         'STORNO: ' || COALESCE(l.line_memo, '')
  FROM public.journal_entry_lines l
  WHERE l.journal_entry_id = p_entry_id;

  UPDATE public.journal_entries SET reversed_by = v_new_id WHERE id = p_entry_id;

  RETURN v_new_id;
END;
$function$;

CREATE OR REPLACE FUNCTION public.reverse_orphaned_document_journals(p_reason text DEFAULT 'Sənədi silinmiş müxabirləşmənin stornosu'::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  r     RECORD;
  v_cnt INTEGER := 0;
BEGIN
  FOR r IN SELECT id FROM public.gl_orphaned_document_entries LOOP
    PERFORM public.reverse_journal_entry(r.id, p_reason);
    v_cnt := v_cnt + 1;
  END LOOP;
  RETURN v_cnt;
END;
$function$;

CREATE OR REPLACE FUNCTION public.rollback_mixed_dimensional_sale(p_sale_item_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_details JSONB;
  v_step JSONB;
  v_scrap_id TEXT;
BEGIN
  SELECT polywood_cut_details INTO v_details FROM sale_items WHERE id = p_sale_item_id;
  IF v_details IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'noop', true);
  END IF;

  FOR v_scrap_id IN SELECT jsonb_array_elements(v_details -> 'scrap_created') ->> 'piece_id'
  LOOP
    DELETE FROM polywood_pieces WHERE id = v_scrap_id::uuid;
  END LOOP;

  FOR v_step IN SELECT * FROM jsonb_array_elements(v_details -> 'steps')
  LOOP
    IF v_step ->> 'action' IN ('consume', 'split_full') THEN
      UPDATE polywood_pieces
      SET status = 'available', sale_item_id = NULL, updated_at = NOW()
      WHERE id = (v_step ->> 'piece_id')::uuid;
    ELSIF v_step ->> 'action' = 'partial' THEN
      UPDATE polywood_pieces
      SET length_m = length_m + COALESCE((v_step ->> 'used_length')::numeric, 0),
          updated_at = NOW()
      WHERE id = (v_step ->> 'piece_id')::uuid;
    END IF;
  END LOOP;

  UPDATE sale_items SET polywood_cut_details = NULL WHERE id = p_sale_item_id;

  RETURN jsonb_build_object('ok', true);
END;
$function$;

CREATE OR REPLACE FUNCTION public.sales_default_posted_when_blank()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.status IS NULL OR btrim(NEW.status) = '' THEN
    NEW.status := 'posted';
  END IF;
  IF NEW.payment_type IS NULL OR btrim(NEW.payment_type) = '' THEN
    NEW.payment_type := 'cash';
  END IF;
  IF NEW.currency IS NULL OR btrim(NEW.currency) = '' THEN
    NEW.currency := 'AZN';
  END IF;
  IF NEW.exchange_rate IS NULL OR NEW.exchange_rate <= 0 THEN
    NEW.exchange_rate := 1;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_account_opening_balance_atomic(p_account_id uuid, p_target_balance numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_target NUMERIC;
  v_ledger NUMERIC;
  v_delta NUMERIC;
  v_name TEXT;
  v_code TEXT;
BEGIN
  IF NOT (
    public.require_permission('can_manage_settings')
    OR public.require_permission('can_manage_finance')
  ) THEN
    RAISE EXCEPTION 'forbidden'
      USING ERRCODE = '42501',
            MESSAGE = 'İlkin qalıq yeniləmək üçün icazəniz yoxdur';
  END IF;

  IF p_account_id IS NULL THEN
    RAISE EXCEPTION 'account_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Hesab identifikatoru tələb olunur';
  END IF;

  v_target := GREATEST(COALESCE(p_target_balance, 0), 0);

  SELECT name, code INTO v_name, v_code
  FROM accounts
  WHERE id = p_account_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'account_not_found'
      USING ERRCODE = 'P0002',
            MESSAGE = 'Hesab tapılmadı';
  END IF;

  DELETE FROM transactions
  WHERE account_id = p_account_id
    AND category = 'İlkin Qalıq';

  SELECT COALESCE(SUM(
    CASE
      WHEN type = 'Mədaxil' THEN amount
      WHEN type = 'Məxaric' THEN -amount
      ELSE 0
    END
  ), 0)
  INTO v_ledger
  FROM transactions
  WHERE account_id = p_account_id;

  v_delta := v_target - COALESCE(v_ledger, 0);

  IF v_delta > 0.0001 THEN
    PERFORM public.post_cash_transaction(
      p_account_id,
      'Mədaxil',
      v_delta,
      'İlkin Qalıq',
      format('İlkin qalıq tənzimləməsi — %s (%s)', v_name, v_code)
    );
  ELSIF v_delta < -0.0001 THEN
    PERFORM public.post_cash_transaction(
      p_account_id,
      'Məxaric',
      ABS(v_delta),
      'İlkin Qalıq',
      format('İlkin qalıq tənzimləməsi (azaldılma) — %s (%s)', v_name, v_code)
    );
  END IF;

  PERFORM public.reconcile_account_balance_atomic(p_account_id);

  RETURN jsonb_build_object(
    'account_id', p_account_id,
    'target_balance', v_target,
    'ledger_balance', (
      SELECT balance FROM accounts WHERE id = p_account_id
    )
  );
END;
$function$;

CREATE OR REPLACE FUNCTION public.set_customer_opening_balance_atomic(p_customer_id uuid, p_opening_balance numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_old NUMERIC;
  v_new NUMERIC := GREATEST(COALESCE(p_opening_balance, 0), 0);
  v_delta NUMERIC;
BEGIN
  SELECT COALESCE(opening_balance, 0) INTO v_old
  FROM public.customers
  WHERE id = p_customer_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Müştəri tapılmadı';
  END IF;

  v_delta := v_new - v_old;

  UPDATE public.customers
  SET opening_balance = v_new
  WHERE id = p_customer_id;

  IF abs(v_delta) > 0.0001 THEN
    PERFORM public.create_journal_entry(jsonb_build_object(
      'document_type', 'customer_opening_balance',
      'document_id', p_customer_id,
      'description', 'Müştəri ilkin qalığı',
      'lines', jsonb_build_array(
        jsonb_build_object(
          'account_code', '1200',
          'debit', GREATEST(v_delta, 0),
          'credit', GREATEST(-v_delta, 0),
          'partner_type', 'customer',
          'partner_id', p_customer_id
        ),
        jsonb_build_object(
          'account_code', '3900',
          'debit', GREATEST(-v_delta, 0),
          'credit', GREATEST(v_delta, 0)
        )
      )
    ));
  END IF;

  RETURN public.refresh_customer_ar_balance(p_customer_id);
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_dimensional_product_fields()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.is_dimensional IS TRUE THEN
    IF NEW.inventory_mode IS NULL OR NEW.inventory_mode = 'standard' THEN
      NEW.inventory_mode := 'polywood';
    END IF;
    IF NEW.base_length IS NOT NULL THEN
      NEW.full_sheet_length_m := NEW.base_length;
    ELSIF NEW.full_sheet_length_m IS NOT NULL THEN
      NEW.base_length := NEW.full_sheet_length_m;
    END IF;
  ELSIF NEW.inventory_mode = 'polywood' THEN
    NEW.is_dimensional := TRUE;
    IF NEW.base_length IS NULL THEN
      NEW.base_length := COALESCE(NEW.full_sheet_length_m, 4);
    END IF;
    IF NEW.full_sheet_length_m IS NULL THEN
      NEW.full_sheet_length_m := NEW.base_length;
    END IF;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_journal_entry_document_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.date IS NULL THEN
    NEW.date := COALESCE((NEW.entry_date::timestamptz), NEW.posted_at, NOW());
  END IF;

  IF NEW.document_type IS NULL AND NEW.source_type IS NOT NULL THEN
    NEW.document_type := NEW.source_type;
  END IF;

  IF NEW.document_id IS NULL AND NEW.source_id IS NOT NULL THEN
    NEW.document_id := NEW.source_id;
  END IF;

  IF NEW.description IS NULL AND NEW.memo IS NOT NULL THEN
    NEW.description := NEW.memo;
  END IF;

  IF NEW.source_type IS NULL AND NEW.document_type IS NOT NULL THEN
    NEW.source_type := NEW.document_type;
  END IF;

  IF NEW.source_id IS NULL AND NEW.document_id IS NOT NULL THEN
    NEW.source_id := NEW.document_id;
  END IF;

  IF NEW.memo IS NULL AND NEW.description IS NOT NULL THEN
    NEW.memo := NEW.description;
  END IF;

  IF NEW.entry_date IS NULL AND NEW.date IS NOT NULL THEN
    NEW.entry_date := (NEW.date AT TIME ZONE 'UTC')::date;
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_product_min_stock_level()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.min_stock_level IS NULL OR NEW.min_stock_level = 0 THEN
      NEW.min_stock_level := COALESCE(NEW.min_stock, 0);
    END IF;
    IF NEW.min_stock IS NULL OR (NEW.min_stock = 0 AND COALESCE(NEW.min_stock_level, 0) > 0) THEN
      NEW.min_stock := COALESCE(NEW.min_stock_level, 0);
    END IF;
    NEW.min_stock := COALESCE(NEW.min_stock, 0);
    NEW.min_stock_level := COALESCE(NEW.min_stock_level, NEW.min_stock, 0);
    RETURN NEW;
  END IF;

  IF NEW.min_stock_level IS DISTINCT FROM OLD.min_stock_level THEN
    NEW.min_stock := COALESCE(NEW.min_stock_level, 0);
  ELSIF NEW.min_stock IS DISTINCT FROM OLD.min_stock THEN
    NEW.min_stock_level := COALESCE(NEW.min_stock, 0);
  ELSE
    NEW.min_stock := COALESCE(NEW.min_stock, NEW.min_stock_level, 0);
    NEW.min_stock_level := COALESCE(NEW.min_stock_level, NEW.min_stock, 0);
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_purchase_partner_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.partner_id IS NULL AND NEW.supplier_id IS NOT NULL THEN
    SELECT p.id
    INTO NEW.partner_id
    FROM partners p
    WHERE p.supplier_id = NEW.supplier_id
    LIMIT 1;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.sync_sale_partner_id()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.partner_id IS NULL AND NEW.customer_id IS NOT NULL THEN
    SELECT p.id
    INTO NEW.partner_id
    FROM partners p
    WHERE p.customer_id = NEW.customer_id
    LIMIT 1;
  END IF;
  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.upsert_warehouse_stock_from_product()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_row_id UUID;
BEGIN
  SELECT ws.id
    INTO v_row_id
    FROM public.warehouse_stocks ws
   WHERE ws.product_id = NEW.id
   ORDER BY ws.updated_at DESC NULLS LAST, ws.id
   LIMIT 1;

  IF v_row_id IS NOT NULL THEN
    UPDATE public.warehouse_stocks
       SET current_stock = COALESCE(NEW.stock, 0),
           min_stock_level = COALESCE(NEW.min_stock_level, NEW.min_stock, 0),
           updated_at = NOW()
     WHERE id = v_row_id;
  ELSE
    INSERT INTO public.warehouse_stocks (
      product_id,
      warehouse_id,
      current_stock,
      min_stock_level,
      updated_at
    )
    VALUES (
      NEW.id,
      NULL,
      COALESCE(NEW.stock, 0),
      COALESCE(NEW.min_stock_level, NEW.min_stock, 0),
      NOW()
    );
  END IF;

  RETURN NEW;
END;
$function$;

CREATE OR REPLACE FUNCTION public.user_can_access_own_sales_row(p_created_by uuid, p_seller_id uuid, p_issued_by uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    public.user_record_access_all()
    OR auth.uid() IS NOT DISTINCT FROM p_created_by
    OR auth.uid() IS NOT DISTINCT FROM p_seller_id
    OR auth.uid() IS NOT DISTINCT FROM p_issued_by;
$function$;

CREATE OR REPLACE FUNCTION public.user_can_read_employee_row(p_department text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    public.user_is_admin()
    OR public.user_record_access_all()
    OR public.current_user_department() IS NULL
    OR p_department IS NULL
    OR p_department = public.current_user_department();
$function$;

CREATE OR REPLACE FUNCTION public.user_has_permission(perm text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN coalesce(auth.jwt() ->> 'role', '') = 'service_role' THEN TRUE
    ELSE public.has_permission(perm)
  END;
$function$;

CREATE OR REPLACE FUNCTION public.user_has_warehouse_access(p_warehouse_id uuid)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT
    public.user_is_admin()
    OR p_warehouse_id IS NULL
    OR COALESCE(jsonb_array_length(public.current_user_scopes() -> 'allowed_warehouses'), 0) = 0
    OR (public.current_user_scopes() -> 'allowed_warehouses') @> to_jsonb(p_warehouse_id::text);
$function$;

CREATE OR REPLACE FUNCTION public.user_is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT lower(COALESCE(public.current_user_role_name(), '')) = 'admin';
$function$;

CREATE OR REPLACE FUNCTION public.user_record_access_all()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    public.current_user_scopes() ->> 'record_access',
    'ALL_RECORDS'
  ) IN ('ALL_RECORDS', '"ALL_RECORDS"');
$function$;

CREATE OR REPLACE FUNCTION public.validate_transaction_row()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
  IF NEW.account_id IS NULL THEN
    RAISE EXCEPTION 'account_id_required'
      USING ERRCODE = '22023',
            MESSAGE = 'Kassa/bank hesabı (account_id) mütləqdir';
  END IF;

  IF NEW.amount IS NULL OR NEW.amount <= 0 THEN
    RAISE EXCEPTION 'invalid_amount'
      USING ERRCODE = '22023',
            MESSAGE = 'Əməliyyat məbləği sıfırdan böyük olmalıdır';
  END IF;

  IF NEW.type IS DISTINCT FROM 'Mədaxil' AND NEW.type IS DISTINCT FROM 'Məxaric' THEN
    RAISE EXCEPTION 'invalid_transaction_type'
      USING ERRCODE = '22023',
            MESSAGE = 'Əməliyyat növü Mədaxil və ya Məxaric olmalıdır';
  END IF;

  RETURN NEW;
END;
$function$;
